// Instrument primitives shared by every screen. Each encodes one piece of state the same way everywhere:
// priority (fill = PM-confirmed, dashed = AI suggestion), evidence (signal bars), score (band-ticked bar / arc).
import type { ReactNode } from "react";
import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react";
import type { Evidence, Priority, Status } from "@/lib/types";
import { BANDS, EVIDENCE, EVIDENCE_HELP, STATUS } from "@/lib/labels";
import { fmtDelta, fmtScore } from "@/lib/format";
import "./ui.css";

export function PriorityMark({ p, ai, size = "md" }: { p: Priority | null | undefined; ai?: boolean; size?: "sm" | "md" }) {
  if (!p) return <span className={`pm pm-none pm-${size}`}>–</span>;
  return (
    <span
      className={`pm pm-${p.toLowerCase()} pm-${size}${ai ? " pm-ai" : ""}`}
      title={ai ? `${p} — AI suggests, not yet confirmed by the PM` : `${p} — confirmed by the PM`}
    >
      {p}
      {ai && <span className="pm-ai-tag">AI</span>}
    </span>
  );
}

export function EvidenceMeter({ level, label = false }: { level: Evidence | null | undefined; label?: boolean }) {
  const lit = level ? 5 - Number(level.slice(1)) : 0;
  const tone = lit >= 3 ? "good" : lit === 2 ? "mid" : "low";
  return (
    <span className="ev" title={level ? `${EVIDENCE[level]} — ${EVIDENCE_HELP[level]}` : "No evidence level"}>
      <span className={`ev-bars ev-${tone}`} aria-hidden>
        {[0, 1, 2, 3].map((i) => (
          <i key={i} className={i < lit ? "on" : ""} style={{ height: 4 + i * 3 }} />
        ))}
      </span>
      {label && <span className="ev-label">{level ? EVIDENCE[level] : "No level"}</span>}
      {!label && <span className="sr-only">{level ? EVIDENCE[level] : "No evidence level"}</span>}
    </span>
  );
}

export function ScoreBar({ score, width = 96, showValue = true }: { score: number | null | undefined; width?: number; showValue?: boolean }) {
  const s = score == null ? null : Math.max(0, Math.min(100, score));
  const band = s == null ? "none" : s >= BANDS.Must ? "must" : s >= BANDS.Should ? "should" : "could";
  return (
    <span className="sb" title={s == null ? "Not scored" : `Score ${s.toFixed(1)} of 100 · Must ≥ 60 · Should ≥ 45`}>
      <span className="sb-track" style={{ width }}>
        <span className={`sb-fill sb-${band}`} style={{ width: `${s ?? 0}%` }} />
        <span className="sb-tick" style={{ left: `${BANDS.Should}%` }} />
        <span className="sb-tick" style={{ left: `${BANDS.Must}%` }} />
      </span>
      {showValue && <span className="sb-val num">{fmtScore(s)}</span>}
    </span>
  );
}

/** Gauge for a headline score: 240° sweep, band ticks at Should/Must, wide light numerals. */
export function ScoreArc({ score, size = 168, caption }: { score: number | null | undefined; size?: number; caption?: ReactNode }) {
  const s = score == null ? 0 : Math.max(0, Math.min(100, score));
  const r = size / 2 - 10;
  const cx = size / 2;
  const cy = size / 2;
  const start = 150; // degrees, SVG coordinates (0 = 3 o'clock, clockwise)
  const sweep = 240;
  const pt = (deg: number, rr = r) => {
    const a = (deg * Math.PI) / 180;
    return [cx + rr * Math.cos(a), cy + rr * Math.sin(a)];
  };
  const arc = (from: number, to: number) => {
    const [x1, y1] = pt(from);
    const [x2, y2] = pt(to);
    const large = to - from > 180 ? 1 : 0;
    return `M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`;
  };
  const end = start + (sweep * s) / 100;
  const band = score == null ? "none" : s >= BANDS.Must ? "must" : s >= BANDS.Should ? "should" : "could";
  const tick = (v: number) => {
    const d = start + (sweep * v) / 100;
    const [x1, y1] = pt(d, r - 9);
    const [x2, y2] = pt(d, r + 6);
    return <line key={v} x1={x1} y1={y1} x2={x2} y2={y2} className="arc-tick" />;
  };
  return (
    <div className="arc" style={{ width: size, height: size * 0.86 }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-hidden>
        <path d={arc(start, start + sweep)} className="arc-track" />
        {score != null && s > 0.5 && <path d={arc(start, end)} className={`arc-fill arc-${band}`} />}
        {tick(BANDS.Should)}
        {tick(BANDS.Must)}
      </svg>
      <div className="arc-center">
        <div className="instrument arc-num" style={{ fontSize: size * 0.3 }}>{fmtScore(score)}</div>
        {caption && <div className="arc-cap">{caption}</div>}
      </div>
    </div>
  );
}

export function Delta({ d, digits }: { d: number | null | undefined; digits?: number }) {
  if (d == null) return <span className="chip outline">new</span>;
  const tone = d > 0.05 ? "up" : d < -0.05 ? "down" : "";
  const Icon = d > 0.05 ? ArrowUpRight : d < -0.05 ? ArrowDownRight : Minus;
  return (
    <span className={`chip ${tone}`}>
      <Icon aria-hidden />
      {digits === 0 ? `${d > 0 ? "+" : ""}${Math.round(d)}` : fmtDelta(d)}
    </span>
  );
}

const STATUS_TONE: Record<Status, string> = {
  proposed: "blue",
  challenged: "violet",
  approved: "green",
  deferred: "amber",
  rejected: "red",
};
export function StatusLight({ s }: { s: Status }) {
  return <span className={`telltale ${STATUS_TONE[s]}`}>{STATUS[s]}</span>;
}

export function Kbd({ children }: { children: ReactNode }) {
  return <kbd className="kbd">{children}</kbd>;
}

export function Seg<T extends string>({
  value,
  options,
  onChange,
  label,
}: {
  value: T;
  options: { value: T; label: ReactNode; count?: number }[];
  onChange: (v: T) => void;
  label: string;
}) {
  return (
    <div className="seg" role="group" aria-label={label}>
      {options.map((o) => (
        <button key={o.value} type="button" aria-pressed={o.value === value} onClick={() => onChange(o.value)}>
          {o.label}
          {o.count != null && <span className="count">{o.count}</span>}
        </button>
      ))}
    </div>
  );
}

export function Skeleton({ h = 14, w = "100%", r }: { h?: number; w?: number | string; r?: number }) {
  return <div className="skel" style={{ height: h, width: w, borderRadius: r }} />;
}

export function SkeletonBlock({ lines = 4 }: { lines?: number }) {
  return (
    <div className="col" style={{ gap: 10 }}>
      {Array.from({ length: lines }).map((_, i) => (
        <Skeleton key={i} w={`${92 - ((i * 17) % 40)}%`} />
      ))}
    </div>
  );
}

export function ErrorNote({ error, onRetry }: { error: unknown; onRetry?: () => void }) {
  const msg = error instanceof Error ? error.message : String(error);
  return (
    <div className="errnote" role="alert">
      <span className="telltale red">Couldn't load</span>
      <span className="errnote-msg">{msg}</span>
      {onRetry && (
        <button className="btn btn-sm" onClick={onRetry}>
          Try again
        </button>
      )}
    </div>
  );
}

export function Empty({ title, children }: { title: string; children?: ReactNode }) {
  return (
    <div className="empty">
      <div className="empty-title">{title}</div>
      {children && <div className="empty-body">{children}</div>}
    </div>
  );
}

export function Stat({ label, value, sub }: { label: string; value: ReactNode; sub?: ReactNode }) {
  return (
    <div className="stat">
      <div className="stat-label">{label}</div>
      <div className="stat-value num">{value}</div>
      {sub && <div className="stat-sub">{sub}</div>}
    </div>
  );
}
// App chrome: the panoramic status band (top) and the floating dock (bottom). The band answers "where are we in
// the 2-year process, what's waiting, what has it cost" from any screen.
import { useEffect, useState, type ReactNode } from "react";
import { NavLink, useLocation, useNavigate } from "react-router-dom";
import { motion } from "motion/react";
import { Archive, Car, Command, Gauge, Globe2, Inbox, Search, Workflow } from "lucide-react";
import { useAppState, useMeta } from "@/lib/hooks";
import { getActor, setActor } from "@/lib/api";
import { fmtSimDate, fmtUsd } from "@/lib/format";
import "./shell.css";

type NavItem = { to: string; label: string; icon: typeof Gauge; key: string; end?: boolean };
export const NAV: NavItem[] = [
  { to: "/", label: "Briefing", icon: Gauge, key: "1", end: true },
  { to: "/decide", label: "Decide", icon: Inbox, key: "2" },
  { to: "/cars", label: "Cars", icon: Car, key: "3" },
  { to: "/markets", label: "Markets", icon: Globe2, key: "4" },
  { to: "/evidence", label: "Evidence", icon: Archive, key: "5" },
  { to: "/process", label: "Process", icon: Workflow, key: "6" },
];

function Mark() {
  // Successor mark: an instrument arc with a forward tick — no third-party trademark.
  return (
    <svg width="22" height="22" viewBox="0 0 24 24" aria-hidden className="mark">
      <path d="M4.2 16.5a8.5 8.5 0 1 1 15.6 0" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M12 12.6 16.6 8" stroke="var(--blue-hi)" strokeWidth="2.2" strokeLinecap="round" />
      <circle cx="12" cy="12.6" r="1.7" fill="var(--blue-hi)" />
    </svg>
  );
}

function WaveStrip() {
  const { data: s } = useAppState();
  const { data: meta } = useMeta();
  const waves = meta ? Object.entries(meta.waves) : [];
  const cur = s?.current_wave ?? 0;
  return (
    <NavLink to="/process" className="wave-strip" title="The ~2-year requirements process, replayed as three evidence waves">
      <span className="sim">Simulation</span>
      <span className="wave-ticks" aria-hidden>
        {waves.map(([n]) => (
          <i key={n} className={Number(n) < cur ? "done" : Number(n) === cur ? "now" : ""} />
        ))}
      </span>
      {s?.running_job ? (
        <span className="telltale blue pulse">{s.running_job.kind === "wave" ? "Opening next wave…" : "AI is answering…"}</span>
      ) : s?.wave ? (
        <span className="wave-text">
          <b>Wave {cur}</b>
          <span className="muted"> · {s.wave.label.replace(/^Wave \d+ · /, "")} · {fmtSimDate(s.wave.simulated_date)}</span>
        </span>
      ) : (
        <span className="muted">No wave opened</span>
      )}
    </NavLink>
  );
}

function ActorChip() {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(getActor());
  const initials = name
    .replace(/\(.*\)/, "")
    .trim()
    .split(/\s+/)
    .map((w) => w[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
  if (editing)
    return (
      <form
        className="actor-edit"
        onSubmit={(e) => {
          e.preventDefault();
          const v = name.trim() || "Atahan (PM)";
          setActor(v);
          setName(v);
          setEditing(false);
        }}
      >
        <input className="input" autoFocus value={name} onChange={(e) => setName(e.target.value)} onBlur={() => setEditing(false)} aria-label="Acting as" />
      </form>
    );
  return (
    <button className="actor" onClick={() => setEditing(true)} title="Acting as — the named person recorded on every decision. Click to change.">
      <span className="avatar">{initials || "PM"}</span>
      <span className="actor-name">{name}</span>
    </button>
  );
}

function Spend() {
  const { data: s } = useAppState();
  if (!s) return null;
  const pct = Math.min(100, (s.spend_usd / s.budget.total) * 100);
  return (
    <NavLink to="/process?tab=system" className="spend" title={`OpenAI spend ${fmtUsd(s.spend_usd)} of $${s.budget.total} — hard stop at $${s.budget.hard_stop}`}>
      <span className="spend-val num">{fmtUsd(s.spend_usd)}</span>
      <span className="spend-track">
        <span style={{ width: `${pct}%` }} />
        <i style={{ left: `${(s.budget.warn / s.budget.total) * 100}%` }} />
        <i style={{ left: `${(s.budget.hard_stop / s.budget.total) * 100}%` }} />
      </span>
    </NavLink>
  );
}

export function Band({ onOpenPalette }: { onOpenPalette: () => void }) {
  const { data: s } = useAppState();
  const waiting = s ? s.counts.to_review + s.counts.open_proposals : 0;
  return (
    <header className="band">
      <div className="band-left">
        <NavLink to="/" className="brand" aria-label="Successor — briefing">
          <Mark />
          <span className="brand-name">Successor</span>
        </NavLink>
        <span className="band-sep" />
        <WaveStrip />
      </div>
      <div className="band-right">
        {waiting > 0 && (
          <NavLink to="/decide" className="waiting" title="Requirements to review and AI suggestions waiting for your decision">
            <span className="waiting-n num">{waiting}</span> waiting for you
          </NavLink>
        )}
        <Spend />
        <ActorChip />
        <button className="btn btn-sm palette-btn" onClick={onOpenPalette} aria-label="Search and commands">
          <Search />
          <span className="kbd">⌘K</span>
        </button>
      </div>
    </header>
  );
}

export function Dock({ onOpenPalette }: { onOpenPalette: () => void }) {
  const { data: s } = useAppState();
  const loc = useLocation();
  const nav = useNavigate();
  const waiting = s ? s.counts.to_review + s.counts.open_proposals : 0;

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const item = NAV.find((n) => n.key === e.key);
      if (item && !loc.pathname.startsWith("/decide")) {
        e.preventDefault();
        nav(item.to);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [nav, loc.pathname]);

  return (
    <nav className="dock-wrap" aria-label="Main">
      <div className="dock">
        {NAV.map((n) => {
          const active = n.end ? loc.pathname === "/" : loc.pathname.startsWith(n.to);
          return (
            <NavLink key={n.to} to={n.to} end={n.end} className={`dock-item${active ? " active" : ""}`} title={`${n.label}  (${n.key})`}>
              {active && <motion.span layoutId="dock-active" className="dock-active" transition={{ type: "spring", stiffness: 500, damping: 40 }} />}
              <n.icon aria-hidden />
              <span className="dock-label">{n.label}</span>
              {n.to === "/decide" && waiting > 0 && <span className="dock-badge num">{waiting}</span>}
            </NavLink>
          );
        })}
      </div>
      <button className="dock-search" onClick={onOpenPalette} aria-label="Search and commands (⌘K)">
        <Command aria-hidden />
      </button>
    </nav>
  );
}

export function PageHead({ title, lede, actions }: { title: ReactNode; lede?: ReactNode; actions?: ReactNode }) {
  return (
    <div className="page-head">
      <div>
        <h1 className="t-head">{title}</h1>
        {lede && <p className="lede">{lede}</p>}
      </div>
      {actions && <div className="row wrap">{actions}</div>}
    </div>
  );
}
import { useEffect, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "motion/react";
import { X } from "lucide-react";

/** Right-hand sheet for detail that shouldn't cost the PM their place (evidence, findings, sources). */
export function Drawer({ open, onClose, title, sub, children, width }: { open: boolean; onClose: () => void; title: ReactNode; sub?: ReactNode; children: ReactNode; width?: number }) {
  useEffect(() => {
    if (!open) return;
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, onClose]);
  return createPortal(
    <AnimatePresence>
      {open && (
        <>
          <motion.div className="drawer-scrim" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={onClose} />
          <motion.aside
            className="drawer"
            role="dialog"
            aria-modal="true"
            style={width ? { width: `min(${width}px, calc(100vw - 20px))` } : undefined}
            initial={{ x: 40, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: 30, opacity: 0, transition: { duration: 0.16 } }}
            transition={{ duration: 0.34, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="drawer-head">
              <div className="grow">
                <div className="t-title">{title}</div>
                {sub && <div className="muted t-small" style={{ marginTop: 4 }}>{sub}</div>}
              </div>
              <button className="btn btn-ghost btn-icon btn-sm" onClick={onClose} aria-label="Close">
                <X />
              </button>
            </div>
            <div className="drawer-body">{children}</div>
          </motion.aside>
        </>
      )}
    </AnimatePresence>,
    document.body,
  );
}
// Thin client for the local Successor API (`api/`, FastAPI). Every write carries the acting PM in X-Actor;
// the server records it in the append-only audit trail.
import { QueryClient } from "@tanstack/react-query";

const ACTOR_KEY = "successor.actor";
export const DEFAULT_ACTOR = "Atahan (PM)";

export function getActor(): string {
  try {
    return localStorage.getItem(ACTOR_KEY) || DEFAULT_ACTOR;
  } catch {
    return DEFAULT_ACTOR;
  }
}
export function setActor(name: string) {
  try {
    localStorage.setItem(ACTOR_KEY, name);
  } catch {
    /* private mode: fall back to the default actor */
  }
}

export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, {
      method,
      headers: { "Content-Type": "application/json", "X-Actor": getActor() },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    throw new ApiError(0, "The local API isn't reachable. Start it with `uv run python -m api`.");
  }
  if (!res.ok) {
    let msg = `${res.status} ${res.statusText}`;
    try {
      const j = await res.json();
      if (typeof j.detail === "string") msg = j.detail;
      else if (Array.isArray(j.detail)) msg = j.detail.map((d: { msg?: string }) => d.msg).join("; ");
    } catch {
      /* keep status text */
    }
    throw new ApiError(res.status, msg);
  }
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

export const api = {
  get: <T,>(path: string) => request<T>("GET", path),
  post: <T,>(path: string, body?: unknown) => request<T>("POST", path, body ?? {}),
  put: <T,>(path: string, body?: unknown) => request<T>("PUT", path, body ?? {}),
  patch: <T,>(path: string, body?: unknown) => request<T>("PATCH", path, body ?? {}),
};

export function qs(params: Record<string, string | number | boolean | null | undefined>): string {
  const u = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== null && v !== "") u.set(k, String(v));
  const s = u.toString();
  return s ? `?${s}` : "";
}

export const queryClient = new QueryClient({
  defaultOptions: { queries: { staleTime: 15_000, refetchOnWindowFocus: false, retry: 1 } },
});

/** Everything a decision can change; refetched after every write. */
export function invalidateAll() {
  return queryClient.invalidateQueries();
}
// PM language for the data model's codes (same wording as the previous app; AGENTS: keep current terms).
import type { Evidence, Priority, Status } from "./types";

export const CAR: Record<string, string> = { F70: "1 Series", G60: "5 Series", G68: "5 Series LWB", G70: "7 Series" };
export const MARKET: Record<string, string> = { US: "USA", EU: "Europe", CN: "China", RoW: "Rest of world" };
export const MARKET_LONG: Record<string, string> = { US: "United States", EU: "Europe", CN: "China", RoW: "Rest of world" };
export const EVIDENCE: Record<Evidence, string> = {
  E1: "Strong evidence",
  E2: "Good evidence",
  E3: "Limited evidence",
  E4: "Assumption only",
};
export const EVIDENCE_HELP: Record<Evidence, string> = {
  E1: "20+ customer comments from 2+ channels, plus study or cited web evidence",
  E2: "15+ comments, or comments plus study/web evidence",
  E3: "a few comments, or study/web evidence only",
  E4: "no direct evidence — forward-looking assumption",
};
export const KANO: Record<string, string> = { basic: "Expected", performance: "Differentiator", delighter: "Delighter" };
export const HORIZON: Record<string, string> = { today: "Needed today", at_successor_launch: "Needed by successor launch" };
export const STATUS: Record<Status, string> = {
  proposed: "To review",
  challenged: "Challenged",
  approved: "Approved",
  deferred: "Deferred",
  rejected: "Rejected",
};
export const PROPOSAL_KIND: Record<string, string> = {
  priority: "Priority change",
  content: "Content edit",
  link_finding: "Evidence link",
  new_requirement: "New requirement",
  extend: "Merge into existing",
  status: "Status",
  review: "To review",
  challenged: "Challenged",
};
export const VERDICT: Record<string, string> = {
  upheld: "You're right",
  partially_upheld: "Partly right",
  not_upheld: "The evidence holds",
};
export const FIT_TYPE: Record<string, { label: string; effect: string }> = {
  brand: { label: "Brand fit", effect: "Gate — a fail blocks approval" },
  compliance: { label: "Compliance", effect: "Gate — a fail blocks approval" },
  segment: { label: "Segment fit", effect: "Shown for context" },
  market: { label: "Market fit", effect: "Adjusts the score" },
  feasibility: { label: "Plant & platform", effect: "Context only, never blocks" },
};
export const REALIZATION: Record<string, string> = {
  carry_over: "Carry over",
  platform_wide: "Platform-wide",
  derivative_specific: "This car only",
  market_variant: "Market variant",
  package: "Package",
};
export const PRIORITIES: Priority[] = ["Must", "Should", "Could"];
export const BANDS = { Must: 60, Should: 45 } as const;

export const car = (v?: string | null) => (v ? CAR[v] ?? v : "–");
export const mkt = (m?: string | null) => (m ? MARKET[m] ?? m : "–");
export const targetLabel = (key: string) => {
  const [v, m] = key.split("×");
  return `${car(v)} · ${mkt(m)}`;
};
export const bandOf = (score: number | null | undefined): Priority | null =>
  score == null ? null : score >= BANDS.Must ? "Must" : score >= BANDS.Should ? "Should" : "Could";
export const fmtScore = (s: number | null | undefined) => (s == null ? "–" : Math.round(s).toString());
export const fmtDelta = (d: number | null | undefined) => (d == null ? "–" : `${d > 0 ? "+" : d < 0 ? "−" : "±"}${Math.abs(d).toFixed(1)}`);
export const fmtUsd = (n: number) => `$${n.toFixed(2)}`;
export const fmtInt = (n: number | null | undefined) => (n == null ? "–" : n.toLocaleString("en-US"));
export const fmtPct = (n: number | null | undefined, digits = 1) => (n == null ? "–" : `${(n * 100).toFixed(digits)}%`);

export function fmtWhen(ts: string | null | undefined): string {
  if (!ts) return "–";
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return ts;
  return d.toLocaleString("en-GB", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });
}

export function fmtSimDate(s: string | null | undefined): string {
  if (!s) return "";
  const [y, m] = s.split("-");
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return m ? `${months[Number(m) - 1]} ${y}` : s;
}

/** Split a markdown bullet string ("- a\n- b") into items. */
export function bullets(s: string | null | undefined): string[] {
  if (!s) return [];
  return s
    .split(/\n+/)
    .map((l) => l.replace(/^\s*[-*•]\s*/, "").trim())
    .filter(Boolean);
}

export const plural = (n: number, one: string, many = `${one}s`) => `${n.toLocaleString("en-US")} ${n === 1 ? one : many}`;

