toolUseResult.stdout:
// Decide: ONE queue for everything that needs the PM — AI priority changes on decided items, merges, new
// requirements to review, AI edits from challenges. Step through it like a rotary controller (J/K), decide with
// a reason, and the next item rolls in. The AI never applies anything itself.
import { useEffect, useMemo, useRef, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useMutation, useQuery } from "@tanstack/react-query";
import { AnimatePresence, motion } from "motion/react";
import { ArrowRight, Check, Clock, ExternalLink, GitMerge, MessageCircleQuestion, PencilLine, SlidersHorizontal, Sparkles, X } from "lucide-react";
import { api, invalidateAll, qs } from "@/lib/api";
import type { Meta, Priority, Proposal, QueueItem, RequirementDetail } from "@/lib/types";
import { PROPOSAL_KIND, targetLabel } from "@/lib/labels";
import { fmtWhen } from "@/lib/format";
import { useMeta } from "@/lib/hooks";
import { Empty, ErrorNote, Kbd, PriorityMark, ScoreBar, SkeletonBlock, StatusLight } from "@/components/ui";
import { AssumptionsBlock, Conflict, DecisionAsk, FitGates, MarketTable, Quotes, ReqTags, StudyAndWeb, VoiceByMarket } from "@/components/req";
import { ChallengeDrawer, OverrideDrawer, ReasonField, reasonOk } from "@/components/actions";
import { useToast } from "@/components/toast";
import "./decide.css";

type Queue = { items: QueueItem[]; counts: Record<string, number> };

const GROUPS: { id: string; label: string; kinds: QueueItem["kind"][]; icon: typeof Clock }[] = [
  { id: "changes", label: "Changes to your decisions", kinds: ["priority"], icon: SlidersHorizontal },
  { id: "merge", label: "Merge into existing", kinds: ["extend"], icon: GitMerge },
  { id: "review", label: "To review", kinds: ["review", "challenged", "new_requirement"], icon: Clock },
  { id: "edits", label: "AI edits & evidence", kinds: ["content", "link_finding"], icon: PencilLine },
];

const isTyping = (e: KeyboardEvent) => {
  const t = e.target as HTMLElement;
  return t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT" || t.isContentEditable);
};

export default function Decide() {
  const { uid } = useParams();
  const nav = useNavigate();
  const { data: meta } = useMeta();
  const [scope, setScope] = useState<string>("");
  const q = useQuery({ queryKey: ["queue", scope], queryFn: () => api.get<Queue>(`/api/queue${qs({ target: scope })}`) });
  const items = q.data?.items ?? [];
  const ordered = useMemo(() => GROUPS.flatMap((g) => items.filter((i) => g.kinds.includes(i.kind))).concat(items.filter((i) => !GROUPS.some((g) => g.kinds.includes(i.kind)))), [items]);
  const idx = Math.max(0, ordered.findIndex((i) => i.uid === uid));
  const current = ordered.find((i) => i.uid === uid) ?? ordered[0] ?? null;
  const [dir, setDir] = useState(1);
  const lastUid = useRef<string | null>(null);

  const goTo = (i: number) => {
    const it = ordered[Math.max(0, Math.min(ordered.length - 1, i))];
    if (!it) return;
    setDir(i >= idx ? 1 : -1);
    nav(`/decide/${encodeURIComponent(it.uid)}`, { replace: true });
  };

  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (isTyping(e) || e.metaKey || e.ctrlKey || e.altKey) return;
      if (e.key === "j" || e.key === "ArrowDown") {
        e.preventDefault();
        goTo(idx + 1);
      } else if (e.key === "k" || e.key === "ArrowUp") {
        e.preventDefault();
        goTo(idx - 1);
      }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  });

  // after a decision the item leaves the queue: roll to whatever now sits at the same position
  const afterDecision = (decidedUid: string) => {
    lastUid.current = decidedUid;
    setDir(1);
    const rest = ordered.filter((i) => i.uid !== decidedUid);
    const next = rest[Math.min(idx, rest.length - 1)];
    nav(next ? `/decide/${encodeURIComponent(next.uid)}` : "/decide", { replace: true });
  };

  return (
    <main className="page decide">
      <aside className="qrail" aria-label="Decision queue">
        <div className="qrail-head">
          <div>
            <h1 className="t-title">Decide</h1>
            <p className="muted t-small">{ordered.length ? `${idx + 1} of ${ordered.length} waiting` : "Queue empty"}</p>
          </div>
          <select className="select qscope" value={scope} onChange={(e) => setScope(e.target.value)} aria-label="Limit the queue to one car · market">
            <option value="">All cars & markets</option>
            {meta?.targets.map((t) => (
              <option key={t.key} value={t.key}>
                {t.label}
              </option>
            ))}
          </select>
        </div>
        {q.isLoading && <SkeletonBlock lines={8} />}
        {q.isError && <ErrorNote error={q.error} onRetry={() => q.refetch()} />}
        <div className="qrail-list">
          {GROUPS.map((g) => {
            const gi = ordered.filter((i) => g.kinds.includes(i.kind));
            if (!gi.length) return null;
            return (
              <section key={g.id} className="qgroup">
                <h2 className="qgroup-h">
                  <g.icon aria-hidden /> {g.label} <span className="num faint">{gi.length}</span>
                </h2>
                {gi.map((it) => (
                  <button
                    key={it.uid}
                    className={`qitem${current?.uid === it.uid ? " on" : ""}`}
                    onClick={() => {
                      setDir(ordered.indexOf(it) >= idx ? 1 : -1);
                      nav(`/decide/${encodeURIComponent(it.uid)}`, { replace: true });
                    }}
                    aria-current={current?.uid === it.uid}
                  >
                    <span className="qitem-title">{it.title}</span>
                    <span className="qitem-sub">
                      {it.kind === "priority" && it.target ? (
                        <>
                          {it.target.label} · <PriorityMark p={it.priority} size="sm" ai />
                        </>
                      ) : (
                        <>
                          {it.is_new_in_wave && <span className="chip blue">new</span>}
                          {it.kind === "challenged" && <span className="chip violet">challenged</span>}
                          <span className="ellipsis">{it.subtitle}</span>
                        </>
                      )}
                      {it.score != null && it.kind !== "priority" && <ScoreBar score={it.score} width={36} />}
                    </span>
                  </button>
                ))}
              </section>
            );
          })}
        </div>
        <div className="qrail-keys faint t-micro">
          <Kbd>J</Kbd> <Kbd>K</Kbd> step · <Kbd>⌘</Kbd>
          <Kbd>↵</Kbd> record
        </div>
      </aside>

      <section className="workspace" aria-live="polite">
        {!q.isLoading && !current && (
          <div className="panel ws-empty">
            <Empty title="Nothing waiting for you">
              Every requirement has a decision and every AI suggestion is answered. New evidence arrives with the next wave — see <Link to="/process">Process</Link>.
            </Empty>
          </div>
        )}
        <AnimatePresence mode="popLayout" initial={false} custom={dir}>
          {current && (
            <motion.div
              key={current.uid}
              custom={dir}
              variants={{
                enter: (d: number) => ({ opacity: 0, y: d * 28, filter: "blur(3px)" }),
                center: { opacity: 1, y: 0, filter: "blur(0px)" },
                exit: (d: number) => ({ opacity: 0, y: d * -22, filter: "blur(3px)", transition: { duration: 0.18 } }),
              }}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{ duration: 0.36, ease: [0.16, 1, 0.3, 1] }}
            >
              {current.type === "requirement" ? (
                <ReviewItem item={current} meta={meta} onDone={() => afterDecision(current.uid)} />
              ) : (
                <ProposalItem item={current} onDone={() => afterDecision(current.uid)} siblings={ordered.filter((i) => i.kind === current.kind)} />
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </section>
    </main>
  );
}

/* ================================================================ review a requirement */

type Choice = "approved" | "deferred" | "rejected";
const CHOICES: { v: Choice; label: string; key: string; icon: typeof Check; tone: string }[] = [
  { v: "approved", label: "Approve", key: "A", icon: Check, tone: "approve" },
  { v: "deferred", label: "Defer", key: "D", icon: Clock, tone: "defer" },
  { v: "rejected", label: "Reject", key: "R", icon: X, tone: "reject" },
];

function ReviewItem({ item, onDone }: { item: QueueItem; meta?: Meta; onDone: () => void }) {
  const q = useQuery({ queryKey: ["requirement", item.req_id], queryFn: () => api.get<RequirementDetail>(`/api/requirements/${item.req_id}`) });
  const r = q.data;
  const toast = useToast();
  const [choice, setChoice] = useState<Choice | null>(null);
  const [why, setWhy] = useState("");
  const [draft, setDraft] = useState<Record<string, Priority | null>>({});
  const [acceptAi, setAcceptAi] = useState(true);
  const [override, setOverride] = useState<string | null>(null);
  const [ask, setAsk] = useState(false);
  const reasonRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    api.post("/api/access", { action: "view", entity_type: "requirement", entity_id: item.req_id }).catch(() => {});
  }, [item.req_id]);

  const blocked = r?.brand_blocked ?? [];
  const unset = r ? r.targets.filter((t) => !t.pm_priority && t.ai_priority && !(t.target.key in draft)).length : 0;
  const changed = Object.entries(draft).filter(([k, v]) => r?.targets.find((t) => t.target.key === k)?.pm_priority !== v);
  const canSubmit = !!choice && reasonOk(why) && !(choice === "approved" && blocked.length > 0);

  const submit = useMutation({
    mutationFn: async () => {
      if (changed.length) await api.put(`/api/requirements/${item.req_id}/priorities`, { priorities: Object.fromEntries(changed), rationale: why });
      return api.post<{ priorities_set: string[] }>(`/api/requirements/${item.req_id}/status`, {
        status: choice,
        rationale: why,
        accept_ai_priorities: acceptAi && choice !== "rejected",
      });
    },
    onSuccess: (res) => {
      const n = changed.length + (res?.priorities_set?.length ?? 0);
      toast({
        tone: "ok",
        title: `${CHOICES.find((c) => c.v === choice)!.label}d · ${item.req_id}`,
        body: n ? `With ${n} market priorit${n === 1 ? "y" : "ies"} confirmed. Recorded in the audit trail.` : "Recorded in the audit trail.",
      });
      invalidateAll();
      onDone();
    },
    onError: (e: Error) => toast({ tone: "error", title: "Not recorded", body: e.message }),
  });

  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
        if (canSubmit && !submit.isPending) submit.mutate();
        return;
      }
      if (isTyping(e) || e.metaKey || e.ctrlKey || e.altKey) return;
      const c = CHOICES.find((x) => x.key.toLowerCase() === e.key.toLowerCase());
      if (c) {
        e.preventDefault();
        setChoice(c.v);
        setTimeout(() => reasonRef.current?.querySelector("textarea")?.focus(), 0);
      }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  });

  if (q.isLoading) return <div className="panel ws-pad"><SkeletonBlock lines={10} /></div>;
  if (q.isError || !r) return <ErrorNote error={q.error} onRetry={() => q.refetch()} />;

  return (
    <article className="ws">
      <header className="ws-head">
        <div className="row wrap" style={{ gap: 10 }}>
          <span className="id">{r.id}</span>
          <StatusLight s={r.status} />
          {item.is_new_in_wave && <span className="chip blue">New in this wave</span>}
          <Link to={`/requirements/${r.id}`} className="ws-open t-small">
            Full trace <ExternalLink size={13} />
          </Link>
        </div>
        <h2 className="ws-title">{r.title}</h2>
        <ReqTags r={r} />
      </header>

      <div className="ws-grid">
        <div className="ws-main">
          <div className="panel ws-pad">
            <DecisionAsk r={r} />
          </div>
          <div className="panel ws-pad">
            <div className="sec-label">What customers say</div>
            <VoiceByMarket r={r} />
            <div style={{ height: 16 }} />
            <Quotes r={r} />
          </div>
          {(r.study.length > 0 || r.web.length > 0) && (
            <div className="panel ws-pad">
              <StudyAndWeb r={r} />
            </div>
          )}
          <Conflict r={r} />
          <div className="panel ws-pad">
            <AssumptionsBlock r={r} />
          </div>
        </div>

        <div className="ws-side">
          <div className="panel">
            <div className="panel-head">
              <h3>Priority by car & market</h3>
              <span className="t-micro faint">Must ≥ 60 · Should ≥ 45</span>
            </div>
            <div className="ws-table">
              <MarketTable r={r} draft={draft} setDraft={setDraft} />
            </div>
          </div>
          <div className="panel ws-pad">
            <div className="sec-label">Fit checks</div>
            <FitGates fit={r.fit} overridden={r.overridden} onOverride={setOverride} />
          </div>

          <div className="panel decision" ref={reasonRef}>
            <div className="decision-choices" role="radiogroup" aria-label="Decision">
              {CHOICES.map((c) => (
                <button key={c.v} role="radio" aria-checked={choice === c.v} className={`dchoice dc-${c.tone}`} onClick={() => setChoice(c.v)}>
                  <c.icon aria-hidden />
                  <span>{c.label}</span>
                  <Kbd>{c.key}</Kbd>
                </button>
              ))}
            </div>
            {choice === "approved" && blocked.length > 0 && (
              <p className="decision-block">Brand-fit fails for {blocked.map(targetLabel).join(", ")}. Override the gate above with a reason first.</p>
            )}
            <ReasonField id="dec-why" value={why} onChange={setWhy} placeholder={choice === "rejected" ? "Why this shouldn't go into the successor…" : "Why — evidence, trade-off, market…"} />
            {choice !== "rejected" && unset > 0 && (
              <label className="check">
                <input type="checkbox" checked={acceptAi} onChange={(e) => setAcceptAi(e.target.checked)} />
                <span>Also confirm the AI's priority for the {unset} market{unset === 1 ? "" : "s"} you haven't set</span>
              </label>
            )}
            <div className="row" style={{ justifyContent: "space-between" }}>
              <button className="btn btn-ghost" onClick={() => setAsk(true)}>
                <MessageCircleQuestion /> Ask the AI
              </button>
              <button className="btn btn-primary" disabled={!canSubmit || submit.isPending} onClick={() => submit.mutate()}>
                {submit.isPending ? "Recording…" : "Record decision"} <Kbd>⌘↵</Kbd>
              </button>
            </div>
          </div>
        </div>
      </div>
      <OverrideDrawer reqId={r.id} target={override} label={override ? targetLabel(override) : ""} onClose={() => setOverride(null)} />
      <ChallengeDrawer reqId={r.id} open={ask} onClose={() => setAsk(false)} />
    </article>
  );
}

/* ================================================================ answer an AI proposal */

function ProposalItem({ item, onDone, siblings }: { item: QueueItem; onDone: () => void; siblings: QueueItem[] }) {
  const all = useQuery({ queryKey: ["proposals", "open"], queryFn: () => api.get<Proposal[]>("/api/proposals?status=open") });
  const p = all.data?.find((x) => x.id === item.proposal_id || `prop:${x.id}` === item.uid);
  const toast = useToast();
  const [why, setWhy] = useState("");
  const [bulk, setBulk] = useState(false);
  const decide = useMutation({
    mutationFn: async (accept: boolean) => {
      if (bulk && siblings.length > 1) {
        const ids = siblings.map((s) => s.proposal_id ?? Number(s.uid.replace("prop:", "")));
        return api.post<{ done: number[]; failed: { id: number; detail: string }[] }>("/api/proposals/bulk-decision", { ids, accept, rationale: why });
      }
      return api.post(`/api/proposals/${p!.id}/decision`, { accept, rationale: why });
    },
    onSuccess: (_r, accept) => {
      toast({ tone: "ok", title: `${accept ? "Accepted" : "Rejected"}${bulk ? ` ${siblings.length} suggestions` : ""}`, body: "Recorded in the audit trail." });
      invalidateAll();
      onDone();
    },
    onError: (e: Error) => toast({ tone: "error", title: "Not recorded", body: e.message }),
  });

  if (all.isLoading) return <div className="panel ws-pad"><SkeletonBlock lines={6} /></div>;
  if (!p) return <ErrorNote error={new Error("This suggestion is no longer open.")} onRetry={() => all.refetch()} />;

  return (
    <article className="ws">
      <header className="ws-head">
        <div className="row wrap" style={{ gap: 10 }}>
          <span className="chip blue">
            <Sparkles /> AI suggests · {PROPOSAL_KIND[p.kind] ?? p.kind}
          </span>
          <span className="id">#{p.id}</span>
          {p.run && <span className="t-small faint">from run {p.run.id} · {fmtWhen(p.run.ts)}</span>}
          <Link to={`/requirements/${p.requirement_id}`} className="ws-open t-small">
            {p.requirement_id} <ExternalLink size={13} />
          </Link>
        </div>
        <h2 className="ws-title">{p.requirement_title}</h2>
      </header>

      <div className="panel ws-pad prop-body">
        {p.kind === "priority" && (
          <div className="prop-priority">
            <div className="prop-target">{p.target?.label}</div>
            <div className="prop-change">
              <div className="col" style={{ gap: 6, alignItems: "center" }}>
                <span className="t-micro faint">Your priority</span>
                <PriorityMark p={(p.old_value as Priority) ?? null} />
              </div>
              <ArrowRight className="prop-arrow" aria-hidden />
              <div className="col" style={{ gap: 6, alignItems: "center" }}>
                <span className="t-micro faint">AI proposes</span>
                <PriorityMark p={(p.proposed_value as Priority) ?? null} ai />
              </div>
              {typeof p.delta?.score === "number" && (
                <div className="col" style={{ gap: 6, alignItems: "center", marginLeft: 18 }}>
                  <span className="t-micro faint">New score</span>
                  <ScoreBar score={p.delta.score as number} width={110} />
                </div>
              )}
            </div>
          </div>
        )}
        {p.kind === "extend" && <ExtendView p={p} />}
        {p.kind === "content" && (
          <div className="diff">
            <div className="sec-label">Field · {p.field.replace(/_/g, " ")}</div>
            <div className="diff-grid">
              <div className="diff-old">
                <div className="t-micro faint">Current</div>
                <p>{p.old_value || "—"}</p>
              </div>
              <div className="diff-new">
                <div className="t-micro" style={{ color: "var(--blue-ink)" }}>Proposed</div>
                <p>{p.proposed_value}</p>
              </div>
            </div>
          </div>
        )}
        {p.kind === "link_finding" && p.finding && (
          <div>
            <div className="sec-label">Link this finding as “{p.proposed_value}”</div>
            <div className="t-title" style={{ fontSize: 16 }}>{p.finding.title}</div>
            <p className="muted" style={{ marginTop: 6 }}>{p.finding.summary}</p>
          </div>
        )}
        {p.kind === "new_requirement" && <p className="t-lead">Accept to keep this new requirement in review; reject to drop it.</p>}
        {p.reason && (
          <div className="prop-cause">
            <div className="sec-label">Why the AI suggests this</div>
            <p>{p.reason}</p>
          </div>
        )}
      </div>

      <div className="panel decision">
        <ReasonField id="prop-why" value={why} onChange={setWhy} placeholder="Why you accept or reject this suggestion…" />
        {siblings.length > 1 && (
          <label className="check">
            <input type="checkbox" checked={bulk} onChange={(e) => setBulk(e.target.checked)} />
            <span>Apply this answer to all {siblings.length} {PROPOSAL_KIND[p.kind]?.toLowerCase()}s in the queue</span>
          </label>
        )}
        <div className="row" style={{ justifyContent: "flex-end" }}>
          <button className="btn btn-danger" disabled={!reasonOk(why) || decide.isPending} onClick={() => decide.mutate(false)}>
            <X /> Reject
          </button>
          <button className="btn btn-primary" disabled={!reasonOk(why) || decide.isPending} onClick={() => decide.mutate(true)}>
            <Check /> Accept
          </button>
        </div>
      </div>
    </article>
  );
}

function ExtendView({ p }: { p: Proposal }) {
  const d = (p.delta ?? {}) as { draft_title?: string; draft_description?: string; targets?: { vehicle_model_id: string; market_code: string; market_note?: string }[] };
  return (
    <div className="col" style={{ gap: 14 }}>
      <div className="extend">
        <div>
          <div className="t-micro faint">Raised again this wave as</div>
          <div className="extend-draft">“{d.draft_title}”</div>
          {d.draft_description && <p className="muted t-small" style={{ marginTop: 6 }}>{d.draft_description}</p>}
        </div>
        <GitMerge className="extend-icon" aria-hidden />
        <div>
          <div className="t-micro faint">Merge into existing</div>
          <div className="extend-draft">{p.requirement_title}</div>
        </div>
      </div>
      {d.targets && d.targets.length > 0 && (
        <div>
          <div className="sec-label">Adds car · market targets</div>
          <div className="row wrap" style={{ gap: 6 }}>
            {d.targets.map((t) => (
              <span key={t.vehicle_model_id + t.market_code} className="chip outline" title={t.market_note}>
                {targetLabel(`${t.vehicle_model_id}×${t.market_code}`)}
              </span>
            ))}
          </div>
        </div>
      )}
      {p.findings && p.findings.length > 0 && (
        <div>
          <div className="sec-label">Brings {p.findings.length} finding(s)</div>
          <ul className="sw-list">{p.findings.slice(0, 6).map((f) => <li key={f.id}>{f.title}</li>)}</ul>
        </div>
      )}
    </div>
  );
}
.decide { display: grid; grid-template-columns: 312px minmax(0, 1fr); gap: 22px; align-items: start; max-width: 1560px; }
@media (max-width: 1000px) { .decide { grid-template-columns: 1fr; } }

/* ---------------------------------------------------------------- queue rail */
.qrail {
  position: sticky; top: calc(var(--band-h) + 20px);
  max-height: calc(100vh - var(--band-h) - 120px);
  display: flex; flex-direction: column; gap: 12px;
}
@media (max-width: 1000px) { .qrail { position: static; max-height: 360px; } }
.qrail-head { display: flex; flex-direction: column; gap: 10px; }
.qscope { height: 32px; padding: 0 10px; font-size: 12.5px; }
.qrail-list { overflow-y: auto; margin-right: -8px; padding-right: 8px; display: flex; flex-direction: column; gap: 14px; }
.qgroup-h { display: flex; align-items: center; gap: 7px; font-size: 11.5px; color: var(--muted); font-weight: 600; margin: 0 0 6px 2px; letter-spacing: 0; }
.qgroup-h svg { width: 13px; height: 13px; }
.qitem {
  position: relative; width: 100%; text-align: left; display: flex; flex-direction: column; gap: 4px;
  padding: 9px 12px 9px 14px; border-radius: 9px; transition: background var(--t-fast);
}
.qitem::before { content: ""; position: absolute; left: 3px; top: 10px; bottom: 10px; width: 2px; border-radius: 2px; background: transparent; transition: background var(--t-fast); }
.qitem:hover { background: var(--hover); }
.qitem.on { background: #131820; box-shadow: inset 0 0 0 1px var(--line-2); }
.qitem.on::before { background: var(--blue-hi); }
.qitem-title { font-size: 13px; font-weight: 550; color: var(--text); line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.qitem-sub { display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--muted); min-width: 0; }
.qitem-sub .ellipsis { min-width: 0; flex: 1; }
.qrail-keys { display: flex; align-items: center; gap: 4px; padding-top: 8px; border-top: 1px solid var(--line); }

/* ---------------------------------------------------------------- workspace */
.workspace { min-width: 0; }
.ws-empty { padding: 40px; }
.ws { display: flex; flex-direction: column; gap: 14px; }
.ws-head { display: flex; flex-direction: column; gap: 10px; padding: 2px 2px 6px; }
.ws-open { margin-left: auto; display: inline-flex; align-items: center; gap: 5px; }
.ws-title { font-size: 30px; line-height: 1.15; font-weight: 600; letter-spacing: -0.02em; font-stretch: 108%; max-width: 30ch; }
.ws-grid { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); gap: 14px; align-items: start; }
@media (max-width: 1280px) { .ws-grid { grid-template-columns: 1fr; } }
.ws-main, .ws-side { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.ws-pad { padding: 18px 20px; }
.ws-table { padding: 4px 6px 8px; overflow-x: auto; }

/* ---------------------------------------------------------------- decision panel */
.decision { padding: 16px 18px 18px; display: flex; flex-direction: column; gap: 14px; border-color: #283245; background: linear-gradient(#10141b, #0e1116); }
.ws-side .decision { position: sticky; bottom: 96px; box-shadow: var(--shadow-2); }
.decision-choices { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.dchoice {
  height: 46px; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-weight: 600; font-size: 14px; color: var(--text-2);
  background: #0b0d11; box-shadow: inset 0 0 0 1px var(--line-2);
  transition: background var(--t-fast), box-shadow var(--t-fast), color var(--t-fast);
}
.dchoice svg { width: 16px; height: 16px; }
.dchoice .kbd { margin-left: 2px; }
.dchoice:hover { color: var(--text); background: var(--hover); }
.dc-approve[aria-checked="true"] { background: var(--green-wash); color: var(--green-ink); box-shadow: inset 0 0 0 1px rgba(60, 207, 145, 0.55); }
.dc-defer[aria-checked="true"] { background: var(--amber-wash); color: var(--amber-ink); box-shadow: inset 0 0 0 1px rgba(245, 165, 36, 0.5); }
.dc-reject[aria-checked="true"] { background: var(--red-wash); color: var(--red-ink); box-shadow: inset 0 0 0 1px rgba(255, 90, 95, 0.5); }
.decision-block { color: var(--red-ink); font-size: 13px; }
.check { display: flex; align-items: flex-start; gap: 9px; font-size: 13px; color: var(--text-2); cursor: pointer; }
.check input { margin-top: 3px; accent-color: var(--blue); width: 15px; height: 15px; }

/* ---------------------------------------------------------------- proposals */
.prop-body { display: flex; flex-direction: column; gap: 18px; }
.prop-target { font-size: var(--fs-small); color: var(--muted); margin-bottom: 14px; }
.prop-change { display: flex; align-items: flex-end; gap: 18px; flex-wrap: wrap; }
.prop-arrow { width: 20px; height: 20px; color: var(--faint); margin-bottom: 2px; }
.prop-cause p { color: var(--text-2); line-height: 1.6; }
.diff-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.diff-old, .diff-new { padding: 12px 14px; border-radius: 10px; background: #0b0d11; box-shadow: inset 0 0 0 1px var(--line); }
.diff-new { box-shadow: inset 0 0 0 1px var(--blue-line); background: rgba(28, 105, 212, 0.06); }
.diff-old p, .diff-new p { margin-top: 6px; font-size: 13.5px; line-height: 1.6; color: var(--text-2); white-space: pre-wrap; }
.diff-old p { color: var(--muted); }
@media (max-width: 760px) { .diff-grid { grid-template-columns: 1fr; } }
.extend { display: grid; grid-template-columns: 1fr auto 1fr; gap: 18px; align-items: center; }
.extend-draft { font-size: 16px; font-weight: 550; margin-top: 4px; line-height: 1.35; }
.extend-icon { width: 22px; height: 22px; color: var(--blue-hi); }
@media (max-width: 760px) { .extend { grid-template-columns: 1fr; } .extend-icon { transform: rotate(90deg); } }

content.content:
// Shapes of the Successor API (contract v1). Codes stay codes here; `labels.ts` turns them into PM language.
export type Priority = "Must" | "Should" | "Could";
export type Evidence = "E1" | "E2" | "E3" | "E4";
export type Status = "proposed" | "challenged" | "approved" | "deferred" | "rejected";
export type FitResult = "pass" | "warn" | "fail" | "overridden";
export type ProposalKind = "priority" | "content" | "link_finding" | "new_requirement" | "extend" | "status";

export interface Target {
  vehicle: string;
  market: string;
  key: string; // "G60×US"
  label: string; // "5 Series · USA"
  car?: string;
  market_label?: string;
}

export interface ZoneDef {
  label: string;
  pos: [number, number, number];
  view: [number, number, number];
  dist: number;
}

export interface WaveInfo {
  label: string;
  simulated_date: string;
  description?: string;
}

export interface Meta {
  actor_default: string;
  vehicles: Record<string, string>;
  markets: Record<string, string>;
  market_names: Record<string, string>;
  targets: Target[];
  focus_targets: string[];
  labels: {
    evidence: Record<string, string>;
    evidence_help: Record<string, string>;
    kano: Record<string, string>;
    horizon: Record<string, string>;
    status: Record<string, string>;
    proposal_kinds: Record<string, string>;
    verdicts?: Record<string, string>;
    fit_types?: Record<string, string>;
    realization?: Record<string, string>;
  };
  priority_bands: { Must: number; Should: number };
  scoring: {
    version: string;
    default_weights: Record<string, number>;
    factor_labels: Record<string, string>;
    confidence: Record<string, number>;
    effort_mod: Record<string, number>;
    market_fit_mod: Record<string, number>;
  };
  editable_fields: string[];
  enums: { horizon: string[]; kano_class: string[]; effort: string[] };
  waves: Record<string, WaveInfo>;
  zones: Record<string, ZoneDef>;
}

export interface AppState {
  current_wave: number;
  wave: WaveInfo | null;
  next_wave: number | null;
  waves_opened: { wave: number; ts: string; actor: string }[];
  spend_usd: number;
  budget: { warn: number; block_non_demo: number; hard_stop: number; total: number };
  running_job: { id: string; kind: string } | null;
  counts: {
    to_review: number;
    open_proposals: number;
    open_by_kind: Partial<Record<ProposalKind, number>>;
    decided: number;
    approved: number;
    requirements: number;
    runs: number;
  };
}

export interface Factor {
  label: string;
  value: number | null;
  weight: number;
  points: number | null;
  available: boolean;
  explanation: string;
}

export interface Breakdown {
  version: string;
  wave?: number;
  score: number;
  base: number;
  evidence_level: Evidence;
  confidence: number;
  modifiers: Record<string, number>;
  factors: Record<string, Factor>;
  gaps: string[];
  gates: Record<string, string | null>;
  verbatims?: { verbatims: number; severity_weighted?: number; channels?: string[] };
  voice_observed?: boolean;
  priority?: Priority;
  cap_note?: string;
  priority_note?: string;
  rationale: string;
  voice_base?: number | null;
  dimensions?: { customer: number | null; business: number | null };
  calibration?: { kind: string; factor: number; note: string } | null;
}

export interface TargetRow {
  target: Target;
  realization: string | null;
  score: number | null;
  ai_priority: Priority | null;
  pm_priority: Priority | null;
  priority: Priority | null;
  ai_only: boolean;
  evidence_level: Evidence | null;
  market_note: string | null;
  brand_gate: FitResult | "–" | null;
  rank: number | null;
}

export interface RequirementSummary {
  id: string;
  title: string;
  category: string;
  status: Status;
  version: number;
  horizon: string | null;
  kano_class: string | null;
  kano_drift: string | null;
  must_not_lose: boolean;
  effort: string | null;
  evidence_level: Evidence | null;
  max_score: number | null;
  best_target: Target | null;
  zone: string;
  brand_blocked: string[];
  targets: TargetRow[];
}

export interface Quote {
  external_id: string;
  market: string;
  country?: string;
  quote: string;
  finding_id?: number;
}

export interface FitRow {
  target: Target;
  check_type: string;
  result: FitResult;
  rationale: string;
  checked_by: string;
  checked_at: string;
}

export interface ChallengeAnswer {
  verdict: "upheld" | "partially_upheld" | "not_upheld";
  answer: string;
  evidence_for: string[];
  evidence_against: string[];
  proposed_edits: { field: string; new_value: string; reason: string }[];
  link_finding_ids: number[];
}

export interface Proposal {
  id: number;
  kind: ProposalKind;
  status: "open" | "accepted" | "rejected" | "superseded";
  requirement_id: string;
  requirement_title: string;
  requirement_status: Status;
  target: Target | null;
  vehicle?: string | null;
  market?: string | null;
  field: string;
  old_value: string | null;
  proposed_value: string | null;
  reason: string | null;
  run: { id: number; ts: string; trigger: string } | null;
  delta: Record<string, unknown> | null;
  finding?: { id: number; source_kind: string; title: string; summary: string } | null;
  findings?: { id: number; source_kind: string; title: string }[];
  decided_by: string | null;
  decided_at: string | null;
  decision_rationale: string | null;
}

export interface RequirementDetail extends Omit<RequirementSummary, "targets"> {
  description: string | null;
  target_metric: string | null;
  acceptance_criteria: string | null;
  assumptions: string | null;
  uncertainties: string | null;
  conflicting_evidence: string | null;
  created_by: string | null;
  created_at: string;
  derivation: {
    product_decision?: string;
    evidence_summary?: string;
    horizon_reason?: string;
    effort_reason?: string;
    supporting_finding_ids?: number[];
    conflicting_finding_ids?: number[];
    wave?: number;
    prompt?: string;
  } | null;
  assumptions_list: string[];
  uncertainties_list: string[];
  targets: (TargetRow & {
    breakdown: Breakdown | null;
    voice: { verbatims: number; base: number | null; share: number | null; own: boolean } | null;
  })[];
  overridden: string[];
  quotes: Quote[];
  study: { finding_id: number; title: string; type: string; market: string | null; vehicle: string | null; mean?: number; z?: number; scale?: string }[];
  web: { finding_id: number; title: string; type: string; best_tier: string | null; publishers: string[]; newest_date: string | null }[];
  contradicting: { finding_id: number; title: string; source_kind: string }[];
  fit: FitRow[];
  open_proposals: Proposal[];
  challenges: { asked_at: string; actor: string; question: string; answered_at: string | null; model: string | null; answer: ChallengeAnswer | null }[];
}

export interface FeedItem {
  id: string;
  ts: string;
  kind: "proposal" | "decision" | "run" | "wave" | "challenge";
  title: string;
  detail: string | null;
  req_id: string | null;
  target: Target | null;
  actor_type: "human" | "ai" | "system";
  actor: string;
  chip: { text: string; tone: "up" | "down" | "neutral" | "warn" } | null;
}

export interface PulseCell {
  target: Target;
  n: number;
  must: number;
  should: number;
  could: number;
  approved: number;
  pm_confirmed: number;
  voice_base: number;
  gaps: string[];
  top: { req_id: string; title: string; score: number; priority: Priority } | null;
}

export interface Briefing {
  wave: { n: number; label: string; simulated_date: string };
  run: { id: number; ts: string; trigger: string; initiated_by: string } | null;
  previous_run_id: number | null;
  headline: { new_requirements: number; priority_changes: number; risers: number; fallers: number; merges_open: number; conflicts: number };
  movers: { req_id: string; title: string; target: Target; score_old: number | null; score_new: number | null; delta: number; priority_old: Priority | null; priority_new: Priority | null; cause: string | null }[];
