.sec-label { font-size: var(--fs-small); color: var(--muted); font-weight: 550; margin-bottom: 8px; }

/* decision ask */
.ask-label { font-size: var(--fs-small); color: var(--blue-ink); font-weight: 600; margin-bottom: 8px; }
.ask-text { font-size: 19px; line-height: 1.5; color: #fff; font-weight: 450; max-width: 68ch; }
.ask-text-sm { font-size: 16px; color: var(--text); }
.ask-need { margin-top: 10px; color: var(--text-2); line-height: 1.6; max-width: 72ch; }

/* voice by market */
.voice { display: flex; flex-direction: column; gap: 9px; }
.voice-row { display: grid; grid-template-columns: 150px minmax(60px, 1fr) auto; gap: 12px; align-items: center; font-size: 13px; }
.voice-label { color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.voice-track { height: 6px; background: #1a1e25; border-radius: 3px; overflow: hidden; }
.voice-track span { display: block; height: 100%; background: linear-gradient(90deg, #2f5fa6, var(--blue-hi)); border-radius: 3px; transition: width var(--t-slow) var(--ease-out); }
.voice-num { font-size: 12.5px; white-space: nowrap; }
.voice-silent { grid-column: 2 / -1; color: var(--amber-ink); font-size: 12.5px; }
@media (max-width: 640px) { .voice-row { grid-template-columns: 1fr; gap: 4px; } .voice-silent { grid-column: auto; } }

/* quotes */
.quotes { display: flex; flex-direction: column; gap: 10px; }
.quote { margin: 0; position: relative; padding: 12px 14px 12px 40px; background: #0b0d11; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--line); }
.quote-mark { position: absolute; left: 13px; top: 13px; width: 15px; height: 15px; color: var(--blue-hi); opacity: 0.8; }
.quote blockquote { margin: 0; color: var(--text); line-height: 1.55; font-size: 13.5px; }
.quote figcaption { margin-top: 6px; font-size: 11.5px; color: var(--muted); }

/* study & web */
.sw { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.sw-list { margin: 0; padding-left: 16px; color: var(--text-2); font-size: 13px; line-height: 1.55; display: flex; flex-direction: column; gap: 4px; }
.sw-list li::marker { color: var(--faint); }
@media (max-width: 760px) { .sw { grid-template-columns: 1fr; } }

/* conflict */
.conflict { display: flex; gap: 12px; padding: 14px 16px; border-radius: 10px; background: var(--amber-wash); box-shadow: inset 0 0 0 1px rgba(245, 165, 36, 0.25); }
.conflict svg { width: 18px; height: 18px; color: var(--amber); flex: none; margin-top: 1px; }
.conflict-title { font-weight: 600; color: var(--amber-ink); margin-bottom: 4px; }
.conflict p { color: var(--text-2); font-size: 13px; line-height: 1.55; }

/* market table */
.mt td { padding-top: 9px; padding-bottom: 9px; }
.mt-target { font-weight: 550; white-space: nowrap; }
.mt-focus { background: rgba(28, 105, 212, 0.07); }
.pchoice { display: inline-flex; gap: 3px; padding: 2px; border-radius: 8px; background: #0a0c0f; box-shadow: inset 0 0 0 1px var(--line); }
.pchoice-b { height: 24px; padding: 0 9px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--faint); transition: background var(--t-fast), color var(--t-fast); }
.pchoice-b:hover { color: var(--text); background: var(--hover); }
.pchoice-b[aria-checked="true"].pc-must { background: var(--blue); color: #fff; }
.pchoice-b[aria-checked="true"].pc-should { background: var(--blue-wash); color: var(--blue-ink); box-shadow: inset 0 0 0 1px var(--blue-line); }
.pchoice-b[aria-checked="true"].pc-could { background: #1d2129; color: var(--text-2); box-shadow: inset 0 0 0 1px var(--line-2); }

/* gates */
.gates { display: flex; flex-direction: column; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--line); }
.gate + .gate { border-top: 1px solid var(--line); }
.gate-head { width: 100%; display: grid; grid-template-columns: 150px 70px 1fr 16px; gap: 10px; align-items: center; padding: 10px 14px; text-align: left; border-radius: 10px; }
.gate-head:hover { background: rgba(255,255,255,0.02); }
.gate-word { font-size: 12.5px; color: var(--text-2); font-variant-numeric: tabular-nums; }
.gate-effect { font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gate-chev { width: 15px; height: 15px; color: var(--faint); transition: transform var(--t-fast); }
.gate-chev.up { transform: rotate(180deg); }
.gate-body { padding: 2px 14px 12px; display: flex; flex-direction: column; gap: 10px; }
.gate-why { margin-top: 5px; color: var(--text-2); font-size: 13px; line-height: 1.55; }
.gate-fail { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 0 10px 10px; padding: 10px 12px; border-radius: 8px; background: var(--red-wash); color: var(--red-ink); font-size: 13px; }
.gate-fail svg { width: 16px; height: 16px; }
@media (max-width: 640px) { .gate-head { grid-template-columns: 1fr auto 16px; } .gate-effect { display: none; } }

/* assumptions & uncertainties */
.au { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.au-label { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.au ul { margin: 0; padding-left: 16px; color: var(--text-2); font-size: 13px; line-height: 1.55; display: flex; flex-direction: column; gap: 5px; }
@media (max-width: 760px) { .au { grid-template-columns: 1fr; } }

