                      <td className="hide-md"><Skeleton w={110} h={12} /></td>
                      <td className="r"><Skeleton w={24} h={12} /></td>
                      <td className="r"><Skeleton w={60} h={12} /></td>
                      <td className="r hide-sm"><Skeleton w={20} h={12} /></td>
                      <td className="hide-md"><Skeleton w={100} h={12} /></td>
                      <td className="hide-sm"><Skeleton w={70} h={12} /></td>
                    </tr>
                  ))
                : d?.items.map((it) => <QRow key={it.finding_id} it={it} open={open.has(it.finding_id)} onToggle={() => toggle(it.finding_id)} />)}
            </tbody>
          </table>
        )}
        {d && !q.isError && d.items.length === 0 && (
          <div className="ev-pad">
            <Empty title={vehicle || category ? "No defect-led themes for this filter" : "Nothing to hand over"}>
              {vehicle || category ? "Try another car or category." : "No customer theme is mostly defects in the current evidence."}
            </Empty>
          </div>
        )}
      </div>
    </section>
  );
}

function QRow({ it, open, onToggle }: { it: QualityItem; open: boolean; onToggle: () => void }) {
  const markets = Object.entries(it.markets).filter(([, n]) => (n ?? 0) > 0);
  const quotes = it.quotes ?? [];
  return (
    <Fragment>
      <tr
        className={`clickable${open ? " on" : ""}`}
        tabIndex={0}
        aria-expanded={open}
        onClick={onToggle}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onToggle();
          }
        }}
      >
        <td className="qh-chev">
          <ChevronRight className={open ? "rot" : ""} aria-hidden />
        </td>
        <td className="ev-titlecell">
          <div className="ev-title">{it.title}</div>
          {it.summary && <div className="ev-sum">{it.summary}</div>}
        </td>
        <td className="hide-sm ev-scope">{it.car ?? car(it.vehicle)}</td>
        <td className="hide-md ev-scope">{it.category ?? "–"}</td>
        <td className="r num">{fmtInt(it.n_signals)}</td>
        <td className="r">
          <span className="qh-share">
            <span className="qh-share-track" aria-hidden>
              <span style={{ width: `${Math.round(it.defect_share * 100)}%` }} />
            </span>
            <span className="num">{Math.round(it.defect_share * 100)}%</span>
          </span>
        </td>
        <td className="r hide-sm num">{it.n_high ? <span className="qh-high">{it.n_high}</span> : <span className="faint">0</span>}</td>
        <td className="hide-md qh-mk">
          {markets.length
            ? markets.map(([m, n], i) => (
                <span key={m}>
                  {i > 0 && <span className="faint"> · </span>}
                  {mkt(m)} <span className="num">{n}</span>
                </span>
              ))
            : <span className="faint">–</span>}
        </td>
        <td className="hide-sm" onClick={(e) => e.stopPropagation()}>
          {it.cited_by.length ? (
            <span className="qh-cited">
              {it.cited_by.map((r) => (
                <Link key={r} to={`/requirements/${r}`} className="id qh-req">
                  {r}
                </Link>
              ))}
            </span>
          ) : (
            <span className="faint">–</span>
          )}
        </td>
      </tr>
      {open && (
        <tr className="qh-x">
          <td />
          <td colSpan={8}>
            {quotes.length ? (
              <div className="qh-quotes">
                {quotes.map((q, i) => (
                  <figure key={`${q.external_id}${i}`} className="quote">
                    <QuoteIcon className="quote-mark" aria-hidden />
                    <blockquote>{q.quote}</blockquote>
                    <figcaption>
                      {mkt(q.market)} · <span className="id">{q.external_id}</span>
                    </figcaption>
                  </figure>
                ))}
              </div>
            ) : (
              <p className="muted t-small">No verified defect quote for this theme — open the finding in Findings to read the comments.</p>
            )}
            <div className="qh-x-foot t-small">
              <Link to={`/evidence?f=${it.finding_id}`}>Open the full finding</Link>
              {it.cited_by.length > 0 && (
                <span className="faint show-sm-inline"> · cited by {it.cited_by.join(", ")}</span>
              )}
            </div>
          </td>
        </tr>
      )}
    </Fragment>
  );
}

toolUseResult.content:
// One finding, traced end to end: the customer comments it was built from, the signal the AI read out of each
// comment (type, severity, need, verified quote), the sources behind it and the requirements that cite it.
import { useState, type ReactNode } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { ArrowRight, BadgeCheck, ExternalLink, Quote as QuoteIcon } from "lucide-react";
import { api, qs } from "@/lib/api";
import type { FindingDetail, FindingMarketMetrics, FindingSignal, FindingSource } from "@/lib/types";
import { MARKET, mkt } from "@/lib/labels";
import { fmtInt, fmtPct, fmtSimDate, plural } from "@/lib/format";
import { Drawer } from "@/components/Drawer";
import { Empty, ErrorNote, Skeleton, SkeletonBlock, Stat, StatusLight } from "@/components/ui";
import { FEEDBACK_TONE, FEEDBACK_TYPE, KIND, KindChip, MARKETS, POLARITY, SEVERITY_TONE, TIER, humanize, scopeLabel } from "./shared";

export function FindingDrawer({ id, onClose }: { id: number | null; onClose: () => void }) {
  const detail = useQuery({
    queryKey: ["finding", id],
    queryFn: () => api.get<FindingDetail>(`/api/findings/${id}`),
    enabled: id != null,
  });
  const f = detail.data;
  return (
    <Drawer
      open={id != null}
      onClose={onClose}
      width={720}
      title={f ? f.title : detail.isError ? "Finding" : <Skeleton w={360} h={20} />}
      sub={
        f ? (
          <span className="row wrap" style={{ gap: 8 }}>
            <KindChip kind={f.source_kind} />
            <span>{scopeLabel(f.vehicle, f.market)}</span>
            <span className="faint">·</span>
            <span>Since wave {f.first_wave ?? 1}</span>
            <span className="faint">·</span>
            <span className="id">F{f.id}</span>
          </span>
        ) : undefined
      }
    >
      {detail.isLoading && <SkeletonBlock lines={9} />}
      {detail.isError && <ErrorNote error={detail.error} onRetry={() => detail.refetch()} />}
      {f && <Body f={f} />}
    </Drawer>
  );
}

function Body({ f }: { f: FindingDetail }) {
  const supports = f.used_by.filter((u) => u.relation !== "contradicts").length;
  return (
    <div className="fd">
      <div className="row wrap" style={{ gap: 6 }}>
        {f.category && <span className="chip outline">{f.category}</span>}
        <span className="chip">{humanize(f.type)}</span>
        {f.polarity && <span className="chip">{POLARITY[f.polarity] ?? humanize(f.polarity)}</span>}
      </div>
      {f.summary && <p className="fd-summary">{f.summary}</p>}

      <Chain f={f} supports={supports} />

      {f.source_kind === "verbatim" && f.markets && Object.keys(f.markets).length > 0 && (
        <Section title="Per market" note={`Comment counts as of wave ${f.metrics_wave}`}>
          <MarketMetrics markets={f.markets} />
        </Section>
      )}
      {f.source_kind === "study" && <StudyMetrics f={f} />}
      {f.source_kind === "web" && <WebMetrics f={f} />}

      {f.n_signals > 0 && <Signals f={f} />}

      <Sources f={f} />

      <Section title="Used by" note={f.used_by.length ? plural(f.used_by.length, "requirement") : undefined}>
        {f.used_by.length ? (
          <ul className="fd-used">
            {f.used_by.map((u) => (
              <li key={`${u.req_id}${u.relation}`}>
                <Link to={`/requirements/${u.req_id}`} className="fd-used-link">
                  <span className="id">{u.req_id}</span>
                  <span className="fd-used-title">{u.title}</span>
                  {u.relation === "contradicts" && <span className="chip warn">Contradicts</span>}
                  <StatusLight s={u.status} />
                  <ArrowRight className="fd-used-arrow" aria-hidden />
                </Link>
              </li>
            ))}
          </ul>
        ) : (
          <div className="fd-uncovered">
            <span className="telltale amber">Not covered</span>
            <span className="muted t-small">No requirement cites this finding yet — a candidate when the next wave derives requirements.</span>
          </div>
        )}
      </Section>
    </div>
  );
}

function Section({ title, note, children }: { title: string; note?: ReactNode; children: ReactNode }) {
  return (
    <section className="fd-sec">
      <div className="fd-sec-head">
        <h3>{title}</h3>
        {note && <span className="faint t-micro">{note}</span>}
      </div>
      {children}
    </section>
  );
}

/** The trace as a strip: comments → signals → this finding → requirements. */
function Chain({ f, supports }: { f: FindingDetail; supports: number }) {
  const steps: { n: ReactNode; label: string; tone?: string }[] =
    f.source_kind === "verbatim"
      ? [
          { n: fmtInt(f.n_sources), label: "customer comments" },
          { n: fmtInt(f.n_signals), label: "signals read by the AI" },
          { n: "1", label: "finding" },
          { n: fmtInt(supports), label: supports === 1 ? "requirement" : "requirements", tone: supports ? "" : "amber" },
        ]
      : [
          { n: fmtInt(f.n_sources), label: f.source_kind === "web" ? "cited web sources" : "study items" },
          { n: "1", label: "finding" },
          { n: fmtInt(supports), label: supports === 1 ? "requirement" : "requirements", tone: supports ? "" : "amber" },
        ];
  return (
    <ol className="fd-chain" aria-label="Evidence chain">
      {steps.map((s, i) => (
        <li key={i} className={s.tone ? `tone-${s.tone}` : undefined}>
          <span className="fd-chain-n num">{s.n}</span>
          <span className="fd-chain-l">{s.label}</span>
          {i < steps.length - 1 && <ArrowRight className="fd-chain-arrow" aria-hidden />}
        </li>
      ))}
    </ol>
  );
}

const top = (o: Record<string, number> | undefined, n: number) =>
  Object.entries(o ?? {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, n);

function MarketMetrics({ markets }: { markets: Record<string, FindingMarketMetrics> }) {
  const rows = MARKETS.filter((m) => markets[m]).concat(Object.keys(markets).filter((m) => !MARKETS.includes(m as never)) as never[]);
  return (
    <div className="fd-tablewrap">
      <table className="table fd-mt">
        <thead>
          <tr>
            <th>Market</th>
            <th className="r">Comments</th>
            <th className="r" title="Share of this market's in-scope comments">Share</th>
            <th className="r" title="Comments weighted by severity">Weighted</th>
            <th>Mostly</th>
            <th>Countries</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((m) => {
            const x = markets[m];
            return (
              <tr key={m}>
                <td className="fd-mt-m">{MARKET[m] ?? m}</td>
                <td className="r">{fmtInt(x.verbatims)}</td>
                <td className="r">
                  {fmtPct(x.share)}
                  {x.base != null && <span className="faint"> of {fmtInt(x.base)}</span>}
                </td>
                <td className="r">{x.severity_weighted != null ? x.severity_weighted.toFixed(1) : "–"}</td>
                <td className="fd-mt-types">
                  {top(x.types, 2).map(([t, n]) => (
                    <span key={t}>
                      {FEEDBACK_TYPE[t] ?? humanize(t)} <span className="faint num">{n}</span>
                    </span>
                  ))}
                </td>
                <td className="fd-mt-types">
                  {top(x.countries, 3).map(([c, n]) => (
                    <span key={c}>
                      {c} <span className="faint num">{n}</span>
                    </span>
                  ))}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function StudyMetrics({ f }: { f: FindingDetail }) {
  const m = f.metrics;
  return (
    <Section title="Customer study" note={m.scale ? `Scale ${m.scale.replace("mean_", "mean of ")}` : undefined}>
      <div className="fd-stats">
        <Stat label="Mean score" value={m.mean != null ? m.mean.toFixed(2) : "–"} />
        <Stat label="Against other items" value={m.z != null ? `${m.z > 0 ? "+" : m.z < 0 ? "−" : ""}${Math.abs(m.z).toFixed(2)} z` : "–"} sub={m.z != null ? (m.z >= 0 ? "above the study average" : "below the study average") : undefined} />
        <Stat label="Rank" value={m.rank != null ? `${m.rank}` : "–"} sub={m.n_items ? `of ${m.n_items} items` : undefined} />
      </div>
    </Section>
  );
}

function WebMetrics({ f }: { f: FindingDetail }) {
  const m = f.metrics;
  return (
    <Section title="Web research" note={m.newest_date ? `Newest source ${fmtSimDate(m.newest_date)}` : undefined}>
      <div className="fd-web">
        <div className="row wrap" style={{ gap: 6 }}>
          {Object.entries(m.tiers ?? {})
            .sort()
            .map(([t, n]) => (
              <span key={t} className={`chip ${t === "T1" ? "up" : t === "T2" ? "" : "warn"}`} title={TIER[t]}>
                {t} · {n}
              </span>
            ))}
        </div>
        {m.publishers && m.publishers.length > 0 && <p className="t-small muted">{m.publishers.join(" · ")}</p>}
      </div>
    </Section>
  );
}

/* ---------------------------------------------------------------- signals: finding → signal → verbatim */

function Signals({ f }: { f: FindingDetail }) {
  const [limit, setLimit] = useState(8);
  const q = useQuery({
    queryKey: ["finding", f.id, "signals", limit],
    queryFn: () => api.get<FindingSignal[]>(`/api/findings/${f.id}/signals${qs({ limit })}`),
    placeholderData: (prev) => prev,
  });
  const sigs = q.data ?? [];
  return (
    <Section title="Customer signals" note={`${fmtInt(f.n_signals)} · high severity first`}>
      <p className="fd-explain">
        The AI read each comment into a signal — what kind of feedback, how severe, the need behind it — and checked the quote word for word against the comment.
      </p>
      {q.isLoading && <SkeletonBlock lines={5} />}
      {q.isError && <ErrorNote error={q.error} onRetry={() => q.refetch()} />}
      {sigs.length > 0 && (
        <ol className="fd-signals">
          {sigs.map((s) => (
            <li key={s.signal_id} className="sig">
              <div className="sig-head">
                <span className={`chip ${FEEDBACK_TONE[s.feedback_type] ?? ""}`}>{FEEDBACK_TYPE[s.feedback_type] ?? humanize(s.feedback_type)}</span>
                {s.severity && <span className={`telltale ${SEVERITY_TONE[s.severity] ?? ""}`}>{humanize(s.severity)}</span>}
                {s.topic && <span className="sig-topic ellipsis">{s.topic}</span>}
                {s.support_question && <span className="chip outline" title="The customer asked for help rather than gave feedback">Support question</span>}
              </div>
              {s.need_statement && <p className="sig-need">{s.need_statement}</p>}
              {s.quote && (
                <figure className="sig-quote">
                  <QuoteIcon className="sig-quote-mark" aria-hidden />
                  <blockquote>{s.quote}</blockquote>
                </figure>
              )}
              <div className="sig-meta">
                <span className="id">{s.source.external_id}</span>
                {s.source.market && <span>{mkt(s.source.market)}</span>}
                {s.source.country && <span>{s.source.country}</span>}
                {s.source.channel && <span>{s.source.channel}</span>}
                {s.source.wave != null && <span>Wave {s.source.wave}</span>}
                {s.quote &&
                  (s.quote_verified ? (
                    <span className="sig-verified">
                      <BadgeCheck aria-hidden /> Quote verified
                    </span>
                  ) : (
                    <span className="telltale amber">Quote not verified</span>
                  ))}
              </div>
            </li>
          ))}
        </ol>
      )}
      {f.n_signals > sigs.length && sigs.length > 0 && (
        <button className="btn btn-ghost btn-sm fd-more" onClick={() => setLimit(Math.min(f.n_signals, limit + 40))} disabled={q.isFetching}>
          {q.isFetching ? "Loading…" : `Show ${Math.min(40, f.n_signals - sigs.length)} more of ${fmtInt(f.n_signals)}`}
        </button>
      )}
    </Section>
  );
}

/* ---------------------------------------------------------------- sources, rendered per kind */

function Sources({ f }: { f: FindingDetail }) {
  const [limit, setLimit] = useState(f.source_kind === "verbatim" ? 6 : 30);
  const q = useQuery({
    queryKey: ["finding", f.id, "sources", limit],
    queryFn: () => api.get<FindingSource[]>(`/api/findings/${f.id}/sources${qs({ limit })}`),
    placeholderData: (prev) => prev,
  });
  const src = q.data ?? [];
  const label = f.source_kind === "verbatim" ? "Customer comments" : f.source_kind === "web" ? "Cited sources" : "Study items";
  return (
    <Section title={label} note={`${fmtInt(f.n_sources)} · ${KIND[f.source_kind]?.long ?? f.source_kind}`}>
      {q.isLoading && <SkeletonBlock lines={4} />}
      {q.isError && <ErrorNote error={q.error} onRetry={() => q.refetch()} />}
      {!q.isLoading && !q.isError && src.length === 0 && <Empty title="No sources linked" />}
      {src.length > 0 && (
        <ul className="fd-sources">
          {src.map((s) => (
            <li key={s.id} className="src">
              {s.kind === "web" ? <WebSource s={s} /> : s.kind === "study" ? <StudySource s={s} /> : s.kind === "feedback" ? <FeedbackSource s={s} /> : <OtherSource s={s} />}
            </li>
          ))}
        </ul>
      )}
      {f.n_sources > src.length && src.length > 0 && (
        <button className="btn btn-ghost btn-sm fd-more" onClick={() => setLimit(Math.min(f.n_sources, limit + 30))} disabled={q.isFetching}>
          {q.isFetching ? "Loading…" : `Show ${Math.min(30, f.n_sources - src.length)} more of ${fmtInt(f.n_sources)}`}
        </button>
      )}
    </Section>
  );
}

const Contra = ({ s }: { s: FindingSource }) => (s.relation === "contradicts" ? <span className="chip warn">Contradicts</span> : null);

function FeedbackSource({ s }: { s: FindingSource }) {
  const text = s.quote || s.text;
  return (
    <>
      {text && <p className="src-quote">“{text}”</p>}
      <div className="src-meta">
        <span className="id">{s.external_id}</span>
        {s.market && <span>{mkt(s.market)}</span>}
        {s.country && <span>{s.country}</span>}
        {s.meta.channel && <span>{s.meta.channel}</span>}
        {s.meta.engine && <span>{s.meta.engine}</span>}
        {s.wave != null && <span>Wave {s.wave}</span>}
        <Contra s={s} />
      </div>
    </>
  );
}

function host(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}
const day = (ts: string | null) => (ts ? new Date(ts).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" }) : null);

function WebSource({ s }: { s: FindingSource }) {
  const tier = s.trust_tier;
  return (
    <>
      <div className="src-head">
        <span className="src-pub">{s.meta.publisher ?? (s.url ? host(s.url) : "Web source")}</span>
        {tier && (
          <span className={`chip ${tier === "T1" ? "up" : tier === "T2" ? "" : "warn"}`} title={TIER[tier] ?? tier}>
            {tier}
          </span>
        )}
        <Contra s={s} />
      </div>
      {(s.quote || s.text) && <p className="src-quote">“{s.quote || s.text}”</p>}
      <div className="src-meta">
        <span>{s.published_at ? `Published ${day(s.published_at)}` : "No publish date"}</span>
        {s.retrieved_at && <span>Retrieved {day(s.retrieved_at)}</span>}
        {s.market && <span>{mkt(s.market)}</span>}
        {s.url && (
          <a href={s.url} target="_blank" rel="noreferrer noopener" className="src-url">
            {host(s.url)} <ExternalLink aria-hidden />
          </a>
        )}
      </div>
    </>
  );
}

function StudySource({ s }: { s: FindingSource }) {
  const m = s.meta;
  const z = m.z_within_column;
  return (
    <>
      <div className="src-head">
        <span className="src-pub">{s.external_id}</span>
        <Contra s={s} />
      </div>
      <div className="src-meta">
        {m.mean != null && <span className="num">Mean {Number(m.mean).toFixed(2)}</span>}
        {z != null && <span className="num">z {z > 0 ? "+" : z < 0 ? "−" : ""}{Math.abs(z).toFixed(2)}</span>}
        {m.rank_within_column != null && <span className="num">Rank {m.rank_within_column}{m.n_items_in_column ? ` of ${m.n_items_in_column}` : ""}</span>}
        {s.vehicle && s.market && <span>{scopeLabel(s.vehicle, s.market)}</span>}
        {m.scale && <span>{m.scale.replace("mean_", "scale ")}</span>}
      </div>
    </>
  );
}

function OtherSource({ s }: { s: FindingSource }) {
  return (
    <>
      <div className="src-head">
        <span className="src-pub">{s.external_id ?? s.ref ?? humanize(s.kind)}</span>
        <span className="chip outline">{humanize(s.kind)}</span>
        <Contra s={s} />
      </div>
      {s.text && <p className="src-quote">{s.text}</p>}
    </>
  );
}

// Quality hand-over (D-038): verbatim themes where at least half of the signals are defects. They go to the quality
// teams, not into requirements — unless a requirement already cites them. Expand a row for verified defect quotes.
import { Fragment, useState } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { ChevronRight, Download, Quote as QuoteIcon } from "lucide-react";
import { api, qs } from "@/lib/api";
import type { QualityItem, QualityPayload } from "@/lib/types";
import { car, mkt } from "@/lib/labels";
import { fmtInt } from "@/lib/format";
import { useMeta } from "@/lib/hooks";
import { Empty, ErrorNote, Skeleton, Stat } from "@/components/ui";

type Setter = (patch: Record<string, string | null>, replace?: boolean) => void;

export function QualityTab({ params, setParam, categories }: { params: URLSearchParams; setParam: Setter; categories: string[] }) {
  const { data: meta } = useMeta();
  const vehicle = params.get("car") ?? "";
  const category = params.get("category") ?? "";
  const q = useQuery({
    queryKey: ["quality", vehicle, category],
    queryFn: () => api.get<QualityPayload>(`/api/quality${qs({ vehicle, category })}`),
    placeholderData: (prev) => prev,
  });
  const [open, setOpen] = useState<Set<number>>(new Set());
  const toggle = (id: number) =>
    setOpen((s) => {
      const n = new Set(s);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });
  const d = q.data;
  const share = d?.defect_share_min ?? 0.5;

  return (
    <section className="ev-section" aria-label="Quality hand-over">
      <div className="qh-stats" aria-busy={q.isLoading}>
        {q.isLoading || !d ? (
          Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="stat">
              <Skeleton w={90} h={11} />
              <div style={{ height: 8 }} />
              <Skeleton w={56} h={22} />
            </div>
          ))
        ) : (
          <>
            <Stat label="Issues for quality" value={fmtInt(d.n_issues)} sub={`themes with ≥ ${Math.round(share * 100)}% defect signals`} />
            <Stat label="Signals" value={fmtInt(d.n_signals)} sub="customer comments read as signals" />
            <Stat label="High severity" value={fmtInt(d.n_high)} sub={d.n_signals ? `${Math.round((d.n_high / d.n_signals) * 100)}% of signals` : undefined} />
            <Stat label="Cited by a requirement" value={fmtInt(d.n_cited)} sub="also feed a product decision" />
          </>
        )}
      </div>

      <div className="ev-filters">
        <select className="select ev-select" value={vehicle} onChange={(e) => setParam({ car: e.target.value || null })} aria-label="Car">
          <option value="">All cars</option>
          {meta && Object.entries(meta.vehicles).map(([code, name]) => <option key={code} value={code}>{name}</option>)}
        </select>
        <select className="select ev-select ev-select-wide" value={category} onChange={(e) => setParam({ category: e.target.value || null })} aria-label="Category">
          <option value="">All categories</option>
          {categories.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
        <span className="grow" />
        <a className="btn" href={`/api/quality.csv${qs({ vehicle, category })}`} download="quality_handover.csv" title="Download this list for the quality teams (logged as an export)">
          <Download /> Download CSV
        </a>
      </div>

      <div className={`panel ev-tablewrap${q.isFetching && !q.isLoading ? " ev-refetch" : ""}`}>
        {q.isError ? (
          <div className="ev-pad">
            <ErrorNote error={q.error} onRetry={() => q.refetch()} />
          </div>
        ) : (
          <table className="table ev-table qh-table">
            <colgroup>
              <col className="c-chev" />
              <col />
              <col className="c-car" />
              <col className="c-cat" />
              <col className="c-n" />
              <col className="c-share" />
              <col className="c-n" />
              <col className="c-mk" />
              <col className="c-cited" />
            </colgroup>
            <thead>
              <tr>
                <th aria-label="Expand" />
                <th>Theme</th>
                <th className="hide-sm">Car</th>
                <th className="hide-md">Category</th>
                <th className="r">Signals</th>
                <th className="r">Defects</th>
                <th className="r hide-sm">High</th>
                <th className="hide-md">Markets</th>
                <th className="hide-sm">Cited by</th>
              </tr>
            </thead>
            <tbody>
              {q.isLoading
                ? Array.from({ length: 7 }).map((_, i) => (
                    <tr key={i} aria-hidden>
                      <td />
                      <td><Skeleton w={`${72 - ((i * 11) % 30)}%`} h={13} /></td>
                      <td className="hide-sm"><Skeleton w={70} h={12} /></td>
                      <td className="hide-md"><Skeleton w={110} h={12} /></td>
                      <td className="r"><Skeleton w={24} h={12} /></td>
                      <td className="r"><Skeleton w={60} h={12} /></td>
                      <td className="r hide-sm"><Skeleton w={20} h={12} /></td>
                      <td className="hide-md"><Skeleton w={100} h={12} /></td>
                      <td className="hide-sm"><Skeleton w={70} h={12} /></td>
                    </tr>
                  ))
                : d?.items.map((it) => <QRow key={it.finding_id} it={it} open={open.has(it.finding_id)} onToggle={() => toggle(it.finding_id)} />)}
            </tbody>
          </table>
        )}
        {d && !q.isError && d.items.length === 0 && (
          <div className="ev-pad">
            <Empty title={vehicle || category ? "No defect-led themes for this filter" : "Nothing to hand over"}>
              {vehicle || category ? "Try another car or category." : "No customer theme is mostly defects in the current evidence."}
            </Empty>
          </div>
        )}
      </div>
    </section>
  );
}

function QRow({ it, open, onToggle }: { it: QualityItem; open: boolean; onToggle: () => void }) {
  const markets = Object.entries(it.markets).filter(([, n]) => (n ?? 0) > 0);
  const quotes = it.quotes ?? [];
  return (
    <Fragment>
      <tr
        className={`clickable${open ? " on" : ""}`}
        tabIndex={0}
        aria-expanded={open}
        onClick={onToggle}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onToggle();
          }
        }}
      >
        <td className="qh-chev">
          <ChevronRight className={open ? "rot" : ""} aria-hidden />
        </td>
        <td className="ev-titlecell">
          <div className="ev-title">{it.title}</div>
          {it.summary && <div className="ev-sum">{it.summary}</div>}
        </td>
        <td className="hide-sm ev-scope">{it.car ?? car(it.vehicle)}</td>
        <td className="hide-md ev-scope">{it.category ?? "–"}</td>
        <td className="r num">{fmtInt(it.n_signals)}</td>
        <td className="r">
          <span className="qh-share">
            <span className="qh-share-track" aria-hidden>
              <span style={{ width: `${Math.round(it.defect_share * 100)}%` }} />
            </span>
            <span className="num">{Math.round(it.defect_share * 100)}%</span>
          </span>
        </td>
        <td className="r hide-sm num">{it.n_high ? <span className="qh-high">{it.n_high}</span> : <span className="faint">0</span>}</td>
        <td className="hide-md qh-mk">
          {markets.length
            ? markets.map(([m, n], i) => (
                <span key={m}>
                  {i > 0 && <span className="faint"> · </span>}
                  {mkt(m)} <span className="num">{n}</span>
                </span>
              ))
            : <span className="faint">–</span>}
        </td>
        <td className="hide-sm" onClick={(e) => e.stopPropagation()}>
          {it.cited_by.length ? (
            <span className="qh-cited">
              {it.cited_by.map((r) => (
                <Link key={r} to={`/requirements/${r}`} className="id qh-req">
                  {r}
                </Link>
              ))}
            </span>
          ) : (
            <span className="faint">–</span>
          )}
        </td>
      </tr>
      {open && (
        <tr className="qh-x">
          <td />
          <td colSpan={8}>
            {quotes.length ? (
              <div className="qh-quotes">
                {quotes.map((q, i) => (
                  <figure key={`${q.external_id}${i}`} className="quote">
                    <QuoteIcon className="quote-mark" aria-hidden />
                    <blockquote>{q.quote}</blockquote>
                    <figcaption>
                      {mkt(q.market)} · <span className="id">{q.external_id}</span>
                    </figcaption>
                  </figure>
                ))}
              </div>
            ) : (
              <p className="muted t-small">No verified defect quote for this theme — open the finding in Findings to read the comments.</p>
            )}
            <div className="qh-x-foot t-small">
              <Link to={`/evidence?f=${it.finding_id}`}>Open the full finding</Link>
              {it.cited_by.length > 0 && (
                <span className="faint show-sm-inline"> · cited by {it.cited_by.join(", ")}</span>
              )}
            </div>
          </td>
        </tr>
      )}
    </Fragment>
  );
}

input.content:
/* Evidence — findings library, gaps queue, quality hand-over, finding drawer. */
.ev-section { display: flex; flex-direction: column; gap: 12px; }
.ev-pad { padding: 18px; }

/* ---------------------------------------------------------------- filter bar */
.ev-filters { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.ev-search { position: relative; flex: 1 1 260px; max-width: 380px; display: block; }
.ev-search > svg { position: absolute; left: 11px; top: 50%; width: 15px; height: 15px; transform: translateY(-50%); color: var(--faint); pointer-events: none; }
.ev-search .input { height: 34px; padding-left: 33px; padding-right: 34px; }
.ev-search .input::-webkit-search-cancel-button { display: none; }
.ev-search .kbd { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); pointer-events: none; }
.ev-select {
  width: auto; height: 34px; padding: 0 28px 0 11px; font-size: 13px; color: var(--text-2);
  appearance: none; cursor: pointer;
  background-image: linear-gradient(45deg, transparent 50%, var(--faint) 50%), linear-gradient(135deg, var(--faint) 50%, transparent 50%);
  background-position: calc(100% - 15px) 15px, calc(100% - 11px) 15px;
  background-size: 4px 4px; background-repeat: no-repeat;
  max-width: 190px;
}
.ev-select:hover { border-color: #363c48; color: var(--text); }
.ev-select:focus { border-color: var(--blue-hi); outline: none; }
.ev-select-wide { max-width: 230px; }
.ev-toggles { display: inline-flex; gap: 6px; }
.ev-toggle {
  height: 34px; padding: 0 12px; border-radius: var(--r-ctl);
  font-size: 12.5px; font-weight: 550; color: var(--muted);
  box-shadow: inset 0 0 0 1px var(--line-2);
  display: inline-flex; align-items: center; gap: 8px; white-space: nowrap;
  transition: background var(--t-fast), color var(--t-fast), box-shadow var(--t-fast);
}
.ev-toggle::before {
  content: ""; width: 8px; height: 8px; border-radius: 2px;
  box-shadow: inset 0 0 0 1.5px var(--faint); transition: background var(--t-fast), box-shadow var(--t-fast);
}
.ev-toggle:hover { color: var(--text); background: var(--hover); }
.ev-toggle[aria-pressed="true"] { color: var(--blue-ink); background: var(--blue-wash); box-shadow: inset 0 0 0 1px var(--blue-line); }
.ev-toggle[aria-pressed="true"]::before { background: var(--blue-hi); box-shadow: none; }

/* ---------------------------------------------------------------- summary line */
.ev-summary { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; color: var(--text-2); min-height: 28px; }
.ev-summary b { color: var(--text); font-weight: 600; }
.ev-summary .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--line-2); }
.ev-clear { margin-left: auto; }
.ev-linkish { font: inherit; color: inherit; cursor: pointer; border-radius: 4px; }
.ev-linkish:hover .telltale { color: var(--amber-ink); }
.ev-link { color: var(--blue-ink); }
.ev-link:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---------------------------------------------------------------- table */
.ev-tablewrap { overflow: hidden; transition: opacity var(--t-fast); }
.ev-refetch { opacity: 0.72; }
.ev-table { table-layout: fixed; }
.ev-table th { padding-top: 11px; padding-bottom: 9px; background: #0c0e12; }
.ev-table th:first-child, .ev-table td:first-child { padding-left: 18px; }
.ev-table th:last-child, .ev-table td:last-child { padding-right: 18px; }
.ev-table td { padding-top: 11px; padding-bottom: 11px; }
.ev-table tbody tr.clickable:focus-visible { outline: none; background: var(--hover); box-shadow: inset 2px 0 0 var(--blue-hi); }
.ev-table tbody tr.on { background: #131820; box-shadow: inset 2px 0 0 var(--blue-hi); }
.ev-table col.c-kind { width: 112px; }
.ev-table col.c-scope { width: 178px; }
.ev-table col.c-comments { width: 128px; }
.ev-table col.c-sources { width: 76px; }
.ev-table col.c-used { width: 148px; }

.ev-titlecell { min-width: 0; }
.ev-title { font-weight: 550; color: var(--text); line-height: 1.35; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ev-sum {
  margin-top: 3px; font-size: 12.5px; color: var(--muted); line-height: 1.45;
  display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden;
}
.ev-scope { color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12.5px; }
.ev-dim { color: var(--text-2); }
.ev-used { color: var(--text-2); font-size: 12.5px; }
.ev-kind svg { width: 12px; height: 12px; opacity: 0.85; }
.ev-kind-study { color: #c9bdf5; }
.ev-kind-web { color: var(--blue-ink); }

.ev-comments { display: inline-flex; align-items: center; justify-content: flex-end; gap: 10px; color: var(--text); }
.mbars { display: inline-flex; align-items: flex-end; gap: 3px; }
.mbar { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; }
.mbar i { display: block; width: 4px; border-radius: 1px; background: #262b34; }
.mbar i.on { background: var(--blue-hi); opacity: 0.85; }
.mbar b { font-size: 8px; line-height: 1; font-weight: 600; color: var(--faint); letter-spacing: 0; }

.ev-more { display: flex; align-items: center; gap: 14px; justify-content: center; padding: 6px 0 4px; }

.show-sm, .show-sm-inline { display: none; }
.ev-mobmeta { align-items: center; gap: 8px; margin-top: 7px; font-size: 12px; color: var(--muted); flex-wrap: wrap; }

@media (max-width: 1100px) {
  .ev-table col.c-scope { width: 140px; }
  .hide-md { display: none; }
}
@media (max-width: 760px) {
  .hide-sm, .hide-md { display: none; }
  .show-sm { display: flex; }
  .show-sm-inline { display: inline; }
  .ev-table col.c-kind, .ev-table col.c-scope, .ev-table col.c-sources, .ev-table col.c-used { width: 0; }
  .ev-table col.c-comments { width: 104px; }
  .ev-title { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .ev-search { max-width: none; flex-basis: 100%; }
  .ev-select, .ev-select-wide { flex: 1 1 calc(50% - 4px); max-width: none; }
  .ev-toggles { flex: 1 1 100%; }
  .ev-toggle { flex: 1; justify-content: center; }
  .ev-clear { margin-left: 0; }
  .ev-table th:first-child, .ev-table td:first-child { padding-left: 14px; }
  .ev-table th:last-child, .ev-table td:last-child { padding-right: 14px; }
  .evidence .page-head .seg { max-width: 100%; overflow-x: auto; }
}

/* ---------------------------------------------------------------- quality hand-over */
.qh-stats {
  display: flex; gap: 0; padding: 4px 0 6px; flex-wrap: wrap;
}
.qh-stats .stat { padding: 0 28px; border-left: 1px solid var(--line); min-width: 150px; }
.qh-stats .stat:first-child { padding-left: 2px; border-left: 0; }
.qh-table col.c-chev { width: 40px; }
.qh-table col.c-car { width: 112px; }
.qh-table col.c-cat { width: 168px; }
.qh-table col.c-n { width: 72px; }
.qh-table col.c-share { width: 112px; }
.qh-table col.c-mk { width: 168px; }
.qh-table col.c-cited { width: 124px; }
.qh-table th:first-child, .qh-table td:first-child { padding-left: 14px; padding-right: 0; }
.qh-chev svg { width: 15px; height: 15px; color: var(--faint); transition: transform var(--t-fast) var(--ease-out), color var(--t-fast); display: block; }
.qh-chev svg.rot { transform: rotate(90deg); color: var(--text-2); }
tr.clickable:hover .qh-chev svg { color: var(--text-2); }
.qh-share { display: inline-flex; align-items: center; gap: 8px; justify-content: flex-end; }
.qh-share-track { width: 38px; height: 4px; border-radius: 2px; background: #1e222a; overflow: hidden; }
.qh-share-track span { display: block; height: 100%; background: var(--red); opacity: 0.75; border-radius: 2px; }
.qh-high { color: var(--red-ink); }
.qh-mk { font-size: 12.5px; color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.qh-cited { display: inline-flex; gap: 6px; flex-wrap: wrap; }
.qh-req { color: var(--blue-ink); }
.qh-req:hover { color: var(--blue-hi); }
.ev-table tr.qh-x td { background: #0b0d11; padding-top: 4px; padding-bottom: 16px; }
.qh-quotes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.qh-quotes .quote { background: var(--panel); }
.qh-x-foot { margin-top: 10px; }
@media (max-width: 1100px) { .qh-table col.c-cat, .qh-table col.c-mk { width: 0; } }
@media (max-width: 760px) {
  .qh-quotes { grid-template-columns: 1fr; }
  .qh-stats { display: grid; grid-template-columns: 1fr 1fr; row-gap: 14px; }
  .qh-stats .stat { padding: 0 0 0 14px; min-width: 0; }
  .qh-stats .stat:nth-child(odd) { padding-left: 2px; border-left: 0; }
  .qh-table col.c-car, .qh-table col.c-cited { width: 0; }
  .qh-table col.c-n { width: 60px; }
  .qh-table col.c-share { width: 88px; }
  .qh-share-track { display: none; }
}

/* ---------------------------------------------------------------- finding drawer */
.fd { display: flex; flex-direction: column; gap: 18px; }
.fd-summary { color: var(--text-2); line-height: 1.6; font-size: 14px; max-width: 68ch; }
.fd-explain { color: var(--muted); font-size: 12.5px; line-height: 1.55; margin-bottom: 12px; max-width: 64ch; }
.fd-sec { display: flex; flex-direction: column; padding-top: 16px; border-top: 1px solid var(--line); }
.fd-sec-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 10px; }
.fd-sec-head h3 { font-size: 13.5px; font-weight: 600; letter-spacing: 0; }
.fd-more { align-self: flex-start; margin-top: 8px; margin-left: -10px; }

/* the chain strip */
.fd-chain {
  list-style: none; margin: 0; padding: 12px 14px; display: flex; align-items: center; flex-wrap: wrap; gap: 6px 0;
  border-radius: 10px; background: #0b0d11; box-shadow: inset 0 0 0 1px var(--line);
}
.fd-chain li { display: inline-flex; align-items: baseline; gap: 6px; }
.fd-chain-n { font-size: 17px; font-weight: 400; font-stretch: 112%; color: var(--text); }
.fd-chain-l { font-size: 12px; color: var(--muted); }
.fd-chain li.tone-amber .fd-chain-n { color: var(--amber-ink); }
.fd-chain-arrow { width: 14px; height: 14px; color: var(--faint); margin: 0 12px; align-self: center; }

/* per-market metrics */
.fd-tablewrap { overflow-x: auto; margin: 0 -8px; }
.fd-mt { font-size: 12.5px; }
.fd-mt th, .fd-mt td { padding: 7px 8px; }
.fd-mt td { font-variant-numeric: tabular-nums; }
.fd-mt-m { font-weight: 550; white-space: nowrap; }
.fd-mt-types { color: var(--text-2); white-space: nowrap; }
.fd-mt-types span + span::before { content: "·"; color: var(--faint); margin: 0 6px; }

.fd-stats { display: flex; gap: 28px; flex-wrap: wrap; }
.fd-web { display: flex; flex-direction: column; gap: 8px; }

/* signals */
.fd-signals { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.sig { padding: 12px 0 13px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 7px; }
.sig:first-child { border-top: 0; padding-top: 2px; }
.sig-head { display: flex; align-items: center; gap: 9px; min-width: 0; }
.sig-topic { font-size: 12.5px; color: var(--text-2); min-width: 0; }
.sig-need { font-size: 13.5px; line-height: 1.55; color: var(--text); max-width: 66ch; }
.sig-quote { margin: 0; position: relative; padding: 9px 12px 9px 34px; border-radius: 8px; background: #0b0d11; box-shadow: inset 0 0 0 1px var(--line); }
.sig-quote-mark { position: absolute; left: 11px; top: 11px; width: 13px; height: 13px; color: var(--blue-hi); opacity: 0.75; }
.sig-quote blockquote { margin: 0; font-size: 13px; line-height: 1.55; color: var(--text-2); }
.sig-meta, .src-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 12px; font-size: 11.5px; color: var(--muted); }
.sig-verified { display: inline-flex; align-items: center; gap: 4px; color: var(--green-ink); }
.sig-verified svg { width: 13px; height: 13px; }

/* sources */
.fd-sources { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.src { padding: 10px 0; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 6px; }
.src:first-child { border-top: 0; padding-top: 0; }
.src-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.src-pub { font-weight: 550; font-size: 13px; color: var(--text); }
.src-quote { font-size: 13px; line-height: 1.55; color: var(--text-2); max-width: 66ch; display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.src-url { display: inline-flex; align-items: center; gap: 4px; }
.src-url svg { width: 12px; height: 12px; }

/* used by */
.fd-used { list-style: none; margin: 0 -10px; padding: 0; display: flex; flex-direction: column; }
.fd-used-link {
  display: grid; grid-template-columns: 76px minmax(0, 1fr) auto auto 14px; gap: 10px; align-items: center;
  padding: 9px 10px; border-radius: 8px; color: var(--text); transition: background var(--t-fast);
}
.fd-used-link:hover { background: var(--hover); text-decoration: none; }
.fd-used-title { font-size: 13px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fd-used-arrow { width: 14px; height: 14px; color: var(--faint); }
.fd-used-link:hover .fd-used-arrow { color: var(--blue-hi); }
.fd-used-link .chip:not(.warn) { display: none; }
.fd-uncovered { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
@media (max-width: 560px) {
  .fd-used-link { grid-template-columns: minmax(0, 1fr) auto; }
  .fd-used-link .id, .fd-used-arrow { display: none; }
  .fd-chain-arrow { margin: 0 8px; }
}

