.fd-sources { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.src { padding: 10px 0; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 6px; }
.src:first-child { border-top: 0; padding-top: 0; }
.src-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.src-pub { font-weight: 550; font-size: 13px; color: var(--text); }
.src-quote { font-size: 13px; line-height: 1.55; color: var(--text-2); max-width: 66ch; display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.src-url { display: inline-flex; align-items: center; gap: 4px; }
.src-url svg { width: 12px; height: 12px; }

/* used by */
.fd-used { list-style: none; margin: 0 -10px; padding: 0; display: flex; flex-direction: column; }
.fd-used-link {
  display: grid; grid-template-columns: 76px minmax(0, 1fr) auto auto 14px; gap: 10px; align-items: center;
  padding: 9px 10px; border-radius: 8px; color: var(--text); transition: background var(--t-fast);
}
.fd-used-link:hover { background: var(--hover); text-decoration: none; }
.fd-used-title { font-size: 13px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fd-used-arrow { width: 14px; height: 14px; color: var(--faint); }
.fd-used-link:hover .fd-used-arrow { color: var(--blue-hi); }
.fd-used-link .chip:not(.warn) { display: none; }
.fd-uncovered { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
@media (max-width: 560px) {
  .fd-used-link { grid-template-columns: minmax(0, 1fr) auto; }
  .fd-used-link .id, .fd-used-arrow { display: none; }
  .fd-chain-arrow { margin: 0 8px; }
}

